function fail(code, message, detail) { const e = new Error(message); e.code = code; e.detail = detail; return e; }

// ------------------------------------------------------- validation/compile
function readSummary(ws) {
  const f = path.join(ws, "modbuilder.json");
  if (!fs.existsSync(f)) return null;
  try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return { _invalid: true }; }
}

// Keep the model inside its lane: only src/main/** and modbuilder.json survive,
// Gradle files always come from the pinned template.
function sanitizeWorkspace(ws, rec) {
  for (const f of listFiles(ws)) {
    const ok = f.rel.startsWith("src/main/java/") || f.rel.startsWith("src/main/resources/") || f.rel === "modbuilder.json"
      || f.rel === "build.gradle.kts" || f.rel === "settings.gradle.kts";
    if (!ok) { fs.rmSync(f.abs, { force: true }); event(rec, rec.status, `Removed unexpected file ${f.rel}`); }
  }
  for (const g of ["build.gradle.kts", "settings.gradle.kts"]) fs.copyFileSync(path.join(TEMPLATE, g), path.join(ws, g));
}

function validate(ws, rec) {
  const problems = [];
  const fixes = []; // mechanical fixes made here (reported to the model only if a repair follows)
  const res = path.join(ws, "src/main/resources");
  const ymlPath = path.join(res, "plugin.yml");
  if (fs.existsSync(path.join(res, "paper-plugin.yml"))) problems.push("Use plugin.yml, not paper-plugin.yml: delete src/main/resources/paper-plugin.yml.");
  if (!fs.existsSync(ymlPath)) return { problems: ["src/main/resources/plugin.yml is missing."], yml: null };
  let yml;
  try { yml = YAML.parse(fs.readFileSync(ymlPath, "utf8")); } catch (e) { return { problems: [`plugin.yml is not valid YAML: ${e.message}`], yml: null }; }
  if (!yml || typeof yml !== "object") return { problems: ["plugin.yml is empty."], yml: null };
  if (!/^[A-Za-z0-9_]{1,40}$/.test(String(yml.name || ""))) problems.push("plugin.yml name must be 1-40 letters, digits or underscores.");
  if (!yml.version) problems.push("plugin.yml needs a version.");
  const main = String(yml.main || "");
  if (!/^[a-zA-Z_][\w]*(\.[a-zA-Z_][\w]*)+$/.test(main)) problems.push("plugin.yml main must be a fully-qualified class name.");
  else if (!fs.existsSync(path.join(ws, "src/main/java", main.replace(/\./g, "/") + ".java"))) problems.push(`plugin.yml main is ${main} but src/main/java/${main.replace(/\./g, "/")}.java does not exist.`);
  if (/^(org\.bukkit|io\.papermc|net\.minecraft|com\.destroystokyo|net\.kyori)\./.test(main)) problems.push("The main class must be in your own package.");
  // Pin api-version to the exact Paper version the jar was compiled against.
  // With '1.21' a 1.21.11 build also "loads" on a 1.21.1 server and then crashes
  // on API that version does not have (the Growth incident: Attribute.SCALE ->
  // InvalidPluginException initializing the main class). With '1.21.11' Paper
  // 1.21.1 refuses it cleanly ("Unsupported API version 1.21.11") while 1.21.11+
  // load it. Verified on real Paper 1.21.1 / 1.21.8 / 1.21.11 servers 2026-10-07.
  const apiVersion = rec.mcVersion;
  if (String(yml["api-version"] || "") !== apiVersion) {
    // Mechanical fix, not worth a model round-trip.
    yml["api-version"] = apiVersion;
    fs.writeFileSync(ymlPath, YAML.stringify(yml));
  }
  // getCommand("x") without a plugin.yml entry returns null at runtime -> NPE on enable.
  const declared = new Set(Object.keys((yml.commands && typeof yml.commands === "object") ? yml.commands : {}).map((s) => s.toLowerCase()));
  const java = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
  if (!java.length) problems.push("No Java source files were written.");
  for (const f of java) {
    const text = fs.readFileSync(f.abs, "utf8");
    for (const m of text.matchAll(/getCommand\(\s*"([^"]+)"\s*\)/g)) {
      if (!declared.has(m[1].toLowerCase())) problems.push(`${f.rel} calls getCommand("${m[1]}") but plugin.yml has no command "${m[1]}" (it would crash on enable).`);
    }
    if (/^\s*public\s+final\s+class\s+\w+\s+extends\s+JavaPlugin/m.test(text)) {
      // Mechanical (0.5): drop the modifier instead of spending a model repair on it.
      const fixed = AUTOFIX ? AF.fixMainFinal(text) : null;
      if (fixed) {
        fs.writeFileSync(f.abs, fixed);
        fixes.push({ file: f.rel, line: 0, kind: "main-final", from: "public final class", to: "public class" });
      } else problems.push(`${f.rel}: the main class must not be final.`);
    }
  }
  const total = listFiles(ws, "src").reduce((a, f) => a + f.size, 0);
  if (total > 1.5 * 1024 * 1024) problems.push("The source is too large (over 1.5 MB).");
  return { problems: [...new Set(problems)], yml, fixes };
}

async function compile(ws, rec, ctl) {
  const out = path.join(ws, "build/classes");
  rmrf(path.join(ws, "build")); fs.mkdirSync(out, { recursive: true });
  const cp = fs.readFileSync(path.join(CP_DIR, `${rec.mcVersion}.txt`), "utf8").trim();
  const sources = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")).map((f) => f.abs);
  const r = await run("javac", ["-J-Xmx768m", "--release", "21", "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", out, ...sources],
    { cwd: ws, env: childEnv(false), timeout: 180000, track: ctl });
  ctl.child = null;
  const output = (r.err + r.out).split(ws + "/").join("");
  if (r.code !== 0) return { ok: false, errors: output.slice(0, 12000) };
  // Resources (plugin.yml, config.yml, ...)
  copyDir(path.join(ws, "src/main/resources"), out);
  const jar = path.join(ws, "build/plugin.jar");
  const j = await run("jar", ["--create", "--file", jar, "-C", out, "."], { cwd: ws, env: childEnv(false), timeout: 60000 });
  if (j.code !== 0) return { ok: false, errors: j.err.slice(0, 4000) };
  const warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 10);
  return { ok: true, jar, classes: out, warnings };
}

// ------------------------------------------------------------ pipeline ----
async function runBuild(rec) {
  const ctl = { child: null, cancelled: false };
  running.set(rec.id, ctl);
function srcList(ws) {
  return listFiles(ws).filter((f) => !f.rel.startsWith("build/")).map((f) => ({ path: f.rel, size: f.size }));
}

async function finish(rec, ws, c, yml) {
  const s = readSummary(ws) || {};
  const name = String(yml.name);
  const version = String(yml.version);
  const jarName = `${name}-${version}.jar`;
  const dest = path.join(dirOf(rec.id), "artifact.jar");
  fs.copyFileSync(c.jar, dest);
  const buf = fs.readFileSync(dest);
  rec.jar = { name: jarName, size: buf.length, sha256: crypto.createHash("sha256").update(buf).digest("hex") };
  rec.pluginName = name;
  rec.version = version;
  const arr = (x) => (Array.isArray(x) ? x : []);
  const ymlCommands = yml.commands && typeof yml.commands === "object" ? yml.commands : {};
  const ymlPerms = yml.permissions && typeof yml.permissions === "object" ? yml.permissions : {};
  rec.summary = {
    tagline: str(s.tagline, 200) || String(yml.description || "").slice(0, 200),
    text: str(s.summary, 1500),
    howToUse: arr(s.howToUse).map((x) => str(x, 300)).filter(Boolean).slice(0, 12),
    limitations: arr(s.limitations).map((x) => str(x, 300)).filter(Boolean).slice(0, 8),
    changes: str(s.changes, 600),
  };
  rec.commands = arr(s.commands).length
    ? arr(s.commands).slice(0, 40).map((x) => ({ usage: str(x.usage, 120), description: str(x.description, 300), permission: str(x.permission, 120), whoCanUse: str(x.whoCanUse, 60) }))
    : Object.entries(ymlCommands).map(([k, v]) => ({ usage: (v && v.usage) ? String(v.usage).replace("<command>", k) : `/${k}`, description: str(v && v.description, 300), permission: str(v && v.permission, 120), whoCanUse: "" }));
  rec.permissions = arr(s.permissions).length
    ? arr(s.permissions).slice(0, 60).map((x) => ({ node: str(x.node, 120), description: str(x.description, 300), default: str(x.default, 10) }))
    : Object.entries(ymlPerms).map(([k, v]) => ({ node: k, description: str(v && v.description, 300), default: String((v && v.default) ?? "op") }));
  rec.config = arr(s.config).slice(0, 60).map((x) => ({ key: str(x.key, 120), description: str(x.description, 300), default: str(typeof x.default === "object" ? JSON.stringify(x.default) : x.default, 200) }));
  rec.warnings = [
    ...c.warnings.map((w) => w.replace(/^warning: /, "Compiler: ")),
    ...(rec.safety ? rec.safety.findings.filter((f) => f.severity === "warn").map((f) => `This plugin ${f.message} (${f.where}).`) : []),
  ];
  rec.files = srcList(ws);
  rec.status = "succeeded";
  rec.finishedAt = now();
  rec.events.push({ at: now(), stage: "succeeded", message: `Ready: ${jarName}` });
}
function str(x, n) { return x == null ? "" : String(x).slice(0, n); }

"use strict";
// Static safety scan for generated plugins. Two layers:
//   1. bytecode: `javap -c -p` over every compiled class, matched against
//      invoked owners/methods (cannot be dodged by source formatting tricks);
//   2. source: heuristics that need string literals / context (paths, UUIDs,
//      name checks feeding privileges, encoded blobs).
// Verdict is decided here, never by the model.

const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

// [id, regex over javap output, plain-English message]
const BYTECODE_BLOCK = [
  ["exec", /java\/lang\/(Runtime\.exec|ProcessBuilder|ProcessHandle)/, "runs other programs on the server machine"],
  ["network", /java\/net\/(Socket|ServerSocket|DatagramSocket|MulticastSocket|URL\.(openConnection|openStream)|URLConnection|HttpURLConnection|InetAddress\.getByName)|java\/net\/http\/|java\/nio\/channels\/(Socket|ServerSocket|Datagram)Channel|javax\/net\//, "connects to the internet or other machines"],
