"use strict";
// Export the Minecraft (Paper) knowledge the build service uses -- sheets/<ver>.md and
// rules/failure-rules.json -- in the GameSupport `knowledge` shape (lib/cyrus/games/support.ts):
//   { version, apiSheet: string[], failureRules: [{ id, detect, fix, why }] }
// one pack per supported Paper version. Read-only; prints JSON to stdout.
//
//   node services/modbuilder/tools/export-knowledge.js [1.21.11 ...] > /tmp/minecraft-knowledge.json
//
// Mapping:
//   apiSheet      one line per bullet of the sheet, prefixed with its section ("[Attributes] ...").
//                 Retrieval can select by that tag; the service today injects the whole sheet
//                 (cached prefix, ~4k tokens) because it is cheap and measured to work.
//   failureRules  id <- id; detect <- pattern (a source regex the pre-check runs) or, for rules
//                 that only show up as a compiler warning, "warning:" + the warning regex;
//                 fix <- fix (with $1.. placeholders) or rule; why <- rule + the build ids it came from.
//                 Rules without either regex are prompt-only lessons: detect "".
// The GameSupport shape has no `versions` / `scope` fields: rules are copied into every version
// they apply to, and scope "main" (main class only) is noted in `why`.

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const RULES = JSON.parse(fs.readFileSync(path.join(ROOT, "rules", "failure-rules.json"), "utf8"));
const versions = process.argv.slice(2).length ? process.argv.slice(2)
  : fs.readdirSync(path.join(ROOT, "sheets")).filter((f) => /^\d+\.\d+(\.\d+)?\.md$/.test(f)).map((f) => f.slice(0, -3));

function sheetLines(md) {
  const out = [];
  let section = "";
  for (const raw of md.split("\n")) {
    const line = raw.trim();
    const h = line.match(/^#{2,}\s+(.*)$/);
    if (h) { section = h[1].replace(/\s*\(.*\)\s*$/, "").trim(); continue; }
    const b = line.match(/^[-*]\s+(.*)$/);
    if (b && section) out.push(`[${section}] ${b[1]}`);
  }
  return out;
}

const packs = versions.map((v) => ({
  version: v,
  apiSheet: sheetLines(fs.readFileSync(path.join(ROOT, "sheets", `${v}.md`), "utf8")),
  failureRules: (RULES.rules || [])
    .filter((r) => (r.versions || ["*"]).some((x) => x === "*" || x === v))
    .map((r) => ({
      id: r.id,
      detect: r.pattern || (r.warning ? `warning:${r.warning}` : ""),
      fix: r.fix || r.rule,
      why: `${r.rule}${r.scope === "main" ? " (main class only)" : ""}${r.source && r.source.length ? ` Seen in: ${[].concat(r.source).join("; ")}` : ""}`,
    })),
}));
process.stdout.write(JSON.stringify({ game: "minecraft", rulesVersion: RULES.version, packs }, null, 2) + "\n");

