/**
 * The shared contract for per-game modding support in Cyrus (PURE, client-safe, data + types only).
 * Every supported game has ONE file `lib/cyrus/games/<gameId>.ts` default-exporting a `GameSupport`.
 * The studio, the install flow, the lifecycle warnings, the mod store and the marketing page all read
 * from it, so a fact is written once. Facts must be VERIFIED against the loader's own docs/source
 * (cite the URL in `sources`), never guessed. Where something could not be confirmed, say so in `unknowns`.
 */

/** Where a mod's files must be installed for it to work. */
export type InstallSide = "server" | "client" | "both";

export type GameVersionRule = {
  /** Game/server build the mod targets, as the loader labels it ("1.21.4", "v0.4.x", "Build 42"). */
  version: string;
  status: "current" | "supported" | "legacy" | "unsupported";
  /** Loader/framework version needed with this game version ("BepInEx 5.4.2200", "Oxide 2.0.x"). */
  loaderVersion?: string;
  /** What changed that breaks mods from the previous version (so we can warn). */
  breaking?: string[];
};

export type DangerousApi = {
  /** Regex source matched against generated code; a hit blocks the build or forces a warning. */
  pattern: string;
  severity: "block" | "warn";
  why: string;
};

export type GameSupport = {
  id: string;                    // matches CyrusGame.id in lib/cyrus/games.ts
  name: string;
  /** Plain-language one-liner of what Cyrus builds for this game. */
  builds: string;
  /** Language(s) the mod is written in and the runtime that loads it. */
  language: "Java" | "C#" | "Lua" | "C++" | "JSON/data";
  loader: { name: string; homepage: string; installDocs: string; licenseNote?: string };
  versions: GameVersionRule[];
  /** Where it installs. `reason` is shown to the customer in plain words ("players must also install this"). */
  install: {
    side: InstallSide;
    serverPath: string;          // relative to the game server root
    clientNote?: string;         // what a player must do on their own PC, if side is client/both
    needsRestart: boolean;
    hotReload: boolean;
    packaging: "jar" | "cs-source" | "dll" | "zip" | "lua-folder" | "pak";
    reason: string;
  };
  /** How Cyrus verifies output BEFORE the customer sees it. */
  verification: {
    method: "compile" | "static-lint" | "load-test" | "none";
    notes: string;
    /** Can we run it for real in a sandbox here, or only lint? Be honest. */
    canRunSandbox: boolean;
  };
  dangerousApis: DangerousApi[];
  /** Things that commonly break players' games/servers for this title, with how we avoid them. */
  breakageRisks: { risk: string; guard: string }[];
  /** How a mod becomes "out of date": what signal tells us (game patch, loader update, API removal). */
  outdatedSignals: { signal: string; source: string }[];
  /** Mod categories this game's engine can actually express (ids from lib/cyrus/categories.ts universal set). */
  categories: string[];
  /** Concrete example prompts that work well, for the starter chips. */
  examplePrompts: string[];
  sources: string[];             // URLs verified while writing this file
  unknowns: string[];            // honest list of anything not confirmed
};

#!/usr/bin/env python3
"""Runtime load check for eval jars. Runs ON THE BUILD VM (needs docker, the
Paper server jars in /root/mbeval/paper/paper-<ver>.jar and the mineflayer bot
node_modules in /opt/papertest/bot).

  python3 rtcheck.py <tag> [--stay 70]

For each Paper version that has jars in /root/mbeval/<tag>/jars, starts ONE
throwaway offline-mode Paper server of exactly that version in Docker
(eclipse-temurin:21-jre) with those plugins, lets a bot join, op itself, run
every command once and walk around for --stay seconds, stops the server, and
reads logs/latest.log. A plugin passes when it enabled and no stack trace in the
log mentions its package. Writes /root/mbeval/<tag>/rt.jsonl.
"""
import json, os, re, shutil, subprocess, sys, time, zipfile, argparse

ap = argparse.ArgumentParser()
ap.add_argument("tag")
ap.add_argument("--stay", type=int, default=70)
ap.add_argument("--root", default="/root/mbeval")
ap.add_argument("--only-version", default="")
ap.add_argument("--reparse", action="store_true", help="only re-read existing server logs")
a = ap.parse_args()

tagdir = os.path.join(a.root, a.tag)
results = {}
for l in open(os.path.join(tagdir, "results.jsonl")):
    r = json.loads(l)
    results[r["key"]] = r
jars = sorted(f[:-4] for f in os.listdir(os.path.join(tagdir, "jars")) if f.endswith(".jar"))
byver = {}
for k in jars:
    byver.setdefault(results[k]["v"], []).append(k)


out = []


def plugin_meta(jar):
    with zipfile.ZipFile(jar) as z:
        y = z.read("plugin.yml").decode("utf8", "replace")
    name = re.search(r"^name:\s*['\"]?([\w]+)", y, re.M).group(1)
    main = re.search(r"^main:\s*['\"]?([\w.]+)", y, re.M).group(1)
    cmds = re.findall(r"^  ([a-z0-9_-]+):\s*$", y.split("commands:", 1)[1], re.M) if "commands:" in y else []
    # stop at the permissions block
    if "commands:" in y and "\npermissions:" in y.split("commands:", 1)[1]:
        block = y.split("commands:", 1)[1].split("\npermissions:", 1)[0]
        cmds = re.findall(r"^  ([A-Za-z0-9_-]+):", block, re.M)
    return name, main, cmds


def run_server(v, keys, sd, log):
    shutil.rmtree(sd, ignore_errors=True)
    os.makedirs(os.path.join(sd, "plugins"))
    shutil.copy(os.path.join(a.root, "paper", f"paper-{v}.jar"), os.path.join(sd, "paper.jar"))
    open(os.path.join(sd, "eula.txt"), "w").write("eula=true\n")
    open(os.path.join(sd, "server.properties"), "w").write(
        "online-mode=false\nenable-rcon=true\nrcon.password=rtcheck-local\nrcon.port=25575\nserver-port=25565\n"
        "level-type=minecraft\\:flat\ngenerate-structures=false\nview-distance=4\nsimulation-distance=4\nspawn-protection=0\n"
        "difficulty=easy\nmax-players=4\nmotd=rtcheck\n")
    meta = {}
    cmds = []
    for k in keys:
        jp = os.path.join(tagdir, "jars", f"{k}.jar")
        shutil.copy(jp, os.path.join(sd, "plugins", f"{k}.jar"))
        meta[k] = plugin_meta(jp)
        cmds += ["/" + c for c in meta[k][2]][:6]
    cname = f"rtcheck-{v.replace('.', '-')}"
    subprocess.run(["docker", "rm", "-f", cname], capture_output=True)
    subprocess.run(["docker", "run", "-d", "--name", cname, "--network", "host", "--memory", "2500m", "-v", f"{sd}:/srv", "-w", "/srv",
                    "eclipse-temurin:21-jre", "java", "-Xms1G", "-Xmx2G", "-jar", "paper.jar", "--nogui"], check=True, capture_output=True)
    t0 = time.time()
    up = False
    while time.time() - t0 < 420:
        time.sleep(5)
        if os.path.exists(log) and re.search(r"Done \([\d.,]+s\)!", open(log, errors="replace").read()):
            up = True
            break
    bot = {}
    if up:
        r = subprocess.run(["docker", "run", "--rm", "--network", "host", "-v", "/opt/papertest/bot:/bot:ro", "-v", f"{os.path.dirname(os.path.abspath(__file__))}/rt-bot.js:/bot-run/rt-bot.js:ro",
                            "-e", "NODE_PATH=/bot/node_modules", "-e", "RT_PORT=25565", "-e", "RT_RCON=25575", "-e", f"RT_VERSION={v}",
                            "-e", f"RT_COMMANDS={json.dumps(cmds)}", "-e", f"RT_STAY_MS={a.stay * 1000}", "node:22-bookworm", "node", "/bot-run/rt-bot.js"],
                           capture_output=True, text=True, timeout=a.stay + 400)
        try:
            bot = json.loads(r.stdout.strip().splitlines()[-1])
        except Exception:
            bot = {"error": (r.stdout + r.stderr)[-400:]}
    for _ in range(60):
        st = subprocess.run(["docker", "inspect", "-f", "{{.State.Running}}", cname], capture_output=True, text=True).stdout.strip()
        if st != "true":
            break
        time.sleep(2)
    subprocess.run(["docker", "rm", "-f", cname], capture_output=True)
    if bot.get("kicked") or bot.get("error"):
        print(f"[{v}] bot: kicked={bot.get('kicked')} error={bot.get('error')}", flush=True)
    return up, bot, meta


def parse(v, keys, meta, log, up, bot):
    text = open(log, errors="replace").read() if os.path.exists(log) else ""
    lines = text.splitlines()
    for k in keys:
        name, main, cmdl = meta[k]
        pkg = main.rsplit(".", 1)[0]
        enabled = bool(re.search(rf"\] Enabling {re.escape(name)} v", text))
        enable_err = bool(re.search(rf"Error occurred while enabling {re.escape(name)}|Could not load (?:plugin )?'(?:plugins/)?{re.escape(k)}\.jar'|{re.escape(name)}.*Unsupported API version", text))
        disable_err = bool(re.search(rf"Error occurred while disabling {re.escape(name)}", text))
        excs = []
        for i, l in enumerate(lines):
            # Paper prints frames as "at Name.jar//dev.nxeon.plugins.x.Cls.m(...)" (or "at dev.nxeon...")
            if re.search(rf"\bat (?:\S+?/+)?{re.escape(pkg)}\.", l):
                # walk up to the exception header
                j = i
                while j > 0 and lines[j].lstrip().startswith(("at ", "...", "Caused by")) is True:
                    j -= 1
                excs.append(lines[j].strip()[:240] + " | " + l.strip()[:200])
        excs = list(dict.fromkeys(excs))
        rec = {"key": k, "v": v, "plugin": name, "serverUp": up, "botJoined": bot.get("joined"), "enabled": enabled, "enableError": enable_err,
               "disableError": disable_err, "exceptions": excs[:5], "ok": up and enabled and not enable_err and not disable_err and not excs, "commandsRun": ["/" + c for c in cmdl][:6]}
        out.append(rec)
        print(json.dumps(rec), flush=True)

for v, keys in sorted(byver.items()):
    if a.only_version and v != a.only_version:
        continue
    sd = os.path.join(a.root, "rt", a.tag, v)
    log = os.path.join(sd, "logs", "latest.log")
    if a.reparse:
        meta = {k: plugin_meta(os.path.join(tagdir, "jars", f"{k}.jar")) for k in keys}
        up, bot = True, {"joined": None}
    else:
        up, bot, meta = run_server(v, keys, sd, log)
    parse(v, keys, meta, log, up, bot)

with open(os.path.join(tagdir, "rt.jsonl" if not a.only_version else f"rt-{a.only_version}.jsonl"), "w") as f:
    for r in out:
        f.write(json.dumps(r) + "\n")
print("rt ok", sum(r["ok"] for r in out), "/", len(out))
// Runtime smoke bot for rtcheck.py: joins a throwaway offline-mode Paper server,
// gets op over RCON, runs every plugin command once with no arguments (usage /
// default paths), stays online long enough for minute timers to fire, then
// stops the server. Run with node_modules from mineflayer + rcon-client.
//   RT_PORT RT_RCON RT_VERSION RT_COMMANDS='["/heal","/fly"]' RT_STAY_MS
const mineflayer = require("mineflayer");
const { Rcon } = require("rcon-client");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const port = +process.env.RT_PORT, rport = +process.env.RT_RCON;
  const cmds = JSON.parse(process.env.RT_COMMANDS || "[]");
  const stay = +(process.env.RT_STAY_MS || 70000);
  const out = { joined: false, chat: [], kicked: null, error: null };
  let rcon;
  try {
    rcon = await Rcon.connect({ host: "127.0.0.1", port: rport, password: "rtcheck-local" });
    const bot = mineflayer.createBot({ host: "127.0.0.1", port, username: "RtBot", version: process.env.RT_VERSION, auth: "offline" });
    bot.on("messagestr", (m) => { if (out.chat.length < 200) out.chat.push(m.slice(0, 200)); });
    bot.on("kicked", (r) => { out.kicked = String(typeof r === "string" ? r : JSON.stringify(r)).slice(0, 300); });
    bot.on("error", (e) => { out.error = String(e.message).slice(0, 300); });
    await Promise.race([new Promise((r) => bot.once("spawn", r)), sleep(60000)]);
    out.joined = !!bot.entity;
    if (out.joined) {
      await sleep(2000);
      await rcon.send("op RtBot");
      await sleep(1000);
      for (const c of cmds) { bot.chat(c); await sleep(1500); }
      const t0 = Date.now();
      while (Date.now() - t0 < stay) { await sleep(5000); if (!bot.entity) break; bot.setControlState("forward", true); await sleep(400); bot.setControlState("forward", false); }
      bot.quit();
    }
  } catch (e) { out.error = String(e && e.message || e).slice(0, 300); }
  try { if (rcon) { await rcon.send("stop"); await rcon.end(); } } catch { /* server going down */ }
  console.log(JSON.stringify(out));
  process.exit(0);
})();

