// Cyrus v6: the LISTING contract for a mod (PURE, client-safe). Shared by the studio's listing
// dialog (routing agent), the NxLabs page/storage (community agent: saveModListing) and the mod
// store. The studio calls storage only through lib/cyrus/listing-client.ts.
//
// A listing is what the world sees: title, primary + secondary universal category
// (lib/cyrus/categories.ts), an icon and a short description. Long description, gallery, links,
// changelog and visibility live on the NxLabs page (community agent) and extend this type there.

import { isCyrusCategoryId, normalizeCategory, type AutoSortResult, type CyrusCategoryId } from "./categories";

export type ModListingInput = {
  title: string;
  categoryId: CyrusCategoryId;
  /** Up to two, never containing categoryId. */
  secondaryCategoryIds: CyrusCategoryId[];
  /**
   * null = the default icon (the category glyph). Otherwise one of:
   *  - "glyph:<categoryId>"  a preset category glyph
   *  - "glyph:mono"          a generated monogram (initials of the title on the mod's colour)
   *  - "local:<rootId>"      an uploaded icon kept on the project until NxLabs storage takes it
   *  - "<assetId>"           an asset in the NxLabs (community) store, [A-Za-z0-9_-]{6,64}
   */
  iconAssetId: string | null;
  /** Brief description, plain text, up to LISTING_DESCRIPTION_MAX characters. */
  description: string;
};

/** Where the category came from; the dialog shows "auto-sorted" until the owner overrides it. */
export type ListingCategorySource = "auto" | "owner";

export const LISTING_TITLE_MIN = 2;
export const LISTING_TITLE_MAX = 60; // = lib/cyrus/meta.ts CYRUS_TITLE_MAX
export const LISTING_DESCRIPTION_MAX = 280;
export const LISTING_SECONDARY_MAX = 2;
/** Uploaded icons are re-encoded in the browser to this square size before upload. */
export const LISTING_ICON_PX = 128;
/** Max bytes of an inline (local:) icon data URL kept on a project. */
export const LISTING_ICON_INLINE_MAX = 24_000;

export type ListingField = keyof ModListingInput;
export type ListingErrors = Partial<Record<ListingField, string>>;

const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g;
const ICON_RE = /^(glyph:(mono|[a-z]+)|local:[A-Za-z0-9_-]{1,64}|[A-Za-z0-9_-]{6,64})$/;

export const cleanTitle = (s: string) => s.replace(CONTROL, "").replace(/\s+/g, " ").trim();
export const cleanDescription = (s: string) => s.replace(CONTROL, "").replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();

export function isIconRef(v: unknown): v is string {
  if (typeof v !== "string" || !ICON_RE.test(v)) return false;
  if (v.startsWith("glyph:") && v !== "glyph:mono") return isCyrusCategoryId(v.slice(6));
  return true;
}

/**
