/**
 * Cyrus Pattern Library: the shared schema (PURE, client-safe, types + constants only).
 *
 * A PATTERN is a small, verified building block (one concern: a command router, a YAML store, a
 * chest menu, a cooldown map...) that the build service can hand to the model so it does not have
 * to rediscover the right API for the target version. Patterns are NOT whole mods.
 *
 * Source of truth on disk (so the Node build service, which cannot import TS, reads it directly):
 *   services/modbuilder/library/<game>/patterns/<id>/pattern.json   metadata (hand-written)
 *   services/modbuilder/library/<game>/patterns/<id>/*.java|*.lua…   code, `package __PKG__;`
 *   services/modbuilder/library/<game>/verify.json                  verification records (generated)
 *   services/modbuilder/library/<game>.json                         the BUILT library (generated by
 *       `node services/modbuilder/tools/library.js build`): every pattern + code + contentHash +
 *       verification + computed status. This is the file both the service and lib/cyrus/library/*
 *       read. Never hand-edit it.
 * Licensing rules: /root/agent-notes/cyrus-v6/library/LICENSING-POLICY.md (summarised in
 * docs/DOCUMENTATION.md "Cyrus Pattern Library").
 */

/**
 * The universal Cyrus categories (routing agent, `CYRUS_CATEGORY_IDS` in lib/cyrus/categories.ts on
 * feature/cyrus-v6-routing). Copied here so this file stays import-free until that branch merges;
 * test/cyrus-library.test.ts checks the library only uses these ids.
 */
export const LIBRARY_CATEGORY_IDS = [
  "environment", "creatures", "weapons", "items", "magic", "vehicles", "gameplay", "quests",
  "minigames", "economy", "admin", "utility", "interface", "visuals", "audio", "performance",
] as const;
export type LibraryCategoryId = (typeof LIBRARY_CATEGORY_IDS)[number];

/** SPDX ids a pattern's source may carry, per source kind (LICENSING-POLICY.md section 2). */
export const LIBRARY_LICENSES = {
  nxeon: ["LicenseRef-Nxeon-Authored"],
  "opted-in-build": ["LicenseRef-Cyrus-Contributor-Grant"],
  "third-party": ["MIT-0", "0BSD", "CC0-1.0", "Unlicense", "MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC"],
} as const;
/** Licences whose notice must travel into the customer's jar when a build retrieved the pattern. */
export const NOTICE_REQUIRED = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC"] as const;

export type PatternSource =
  | {
      kind: "nxeon";
      license: "LicenseRef-Nxeon-Authored";
      author: string;
      /** ISO date the pattern was written. */
      retrieved: string;
      notes?: string;
    }
  | {
      kind: "third-party";
      license: (typeof LIBRARY_LICENSES)["third-party"][number];
      author: string;
      url: string;
      /** Exact commit SHA of the file that was read. */
      commit: string;
      retrieved: string;
      /** Exact notice text (copyright line + licence name). Required when the licence needs it. */
      attribution: string;
      modified: boolean;
      notes?: string;
    }
  | {
      kind: "opted-in-build";
      license: "LicenseRef-Cyrus-Contributor-Grant";
      /** Build the pattern was distilled from, and the consent that allowed it (LibraryConsent.id). */
      buildId: string;
      consentId: string;
      consentAt: string;
      retrieved: string;
      notes?: string;
    };

/** How a pattern reaches the model (see "Retrieval" in services/modbuilder/library.js). */
export type PatternRetrieval =
  /** Index line in the cached prefix; full code only when the request's tags match strongly. */
  | "auto"
  /** Index line only; the model Reads the file from the workspace library folder if it wants it.
   *  For COMMON APIs the model already gets right (CloudAPIBench: retrieval can hurt those). */
  | "on-demand";

export type PatternFile = {
  /** Path relative to the plugin's package dir, e.g. "ChestMenu.java". */
  path: string;
  /** Source with `package __PKG__;` (the service/verifier substitutes the real package). */
  code: string;
};

/** One version's verification result. A record is only valid for the contentHash it names. */
export type VerificationRecord = {
  version: string;               // "1.21.4"
  contentHash: string;           // sha256 of the pattern at verification time
  date: string;                  // ISO timestamp
  compile: "pass" | "fail";
  compileErrors?: string;        // first 2k chars when it failed
  /** javac [deprecation]/[removal] warnings (passing, but a drift signal). */
  warnings: string[];
  /** The build service's own safety scan (scan.js) over the pattern's classes. */
  scan: "pass" | "warn" | "block";
  scanFindings?: string[];
  /** Real Paper server of exactly this version, plugin enabled + self-test + clean disable. */
  runtime: "pass" | "fail" | "not-run";
  runtimeDetail?: string;
  /** What the runtime self-test exercised; anything needing a real player client is listed in `needsPlayer`. */
  runtimeCovers?: string[];
  tools: { javac: string; apiJar: string; server?: string; harness: string };
};

export type PatternStatus =
  /** Compiles + scans clean + runtime-loaded on EVERY claimed version, at the current contentHash. */
  | "verified"
  /** Compiles + scans clean on every claimed version; runtime load missing for at least one. */
  | "compiled"
  /** At least one claimed version fails to compile, is blocked by the scan, or failed at runtime. */
  | "failing"
  /** Code or metadata changed since the last verification (hash mismatch), or never verified. */
  | "unverified";

export type LibraryPattern = {
  id: string;                    // kebab-case, stable, unique per game
  game: "minecraft" | string;
  title: string;
  category: LibraryCategoryId;
  secondary?: LibraryCategoryId[];
  /** Feature tags the deterministic selector matches against the request + plan ("cooldown", "gui"). */
  tags: string[];
  /** Words/phrases in a customer prompt that point to this pattern (lower case). */
  triggers: string[];
  /** One line, developer voice: what it gives you. Goes into the index in the cached prefix. */
  summary: string;
  /** When to use it and how to wire it (shown with the code). */
  usage: string;
  /** Classes/APIs the code relies on (for drift checks and the index line). */
  apis: string[];
  /** Other pattern ids this one needs, and anything outside the JDK + game API (must be empty for Minecraft today). */
  requires: string[];
  externalDeps: string[];
  /** Game/loader versions this pattern claims to work on. Every one must verify for `verified`. */
  versions: string[];
  /** plugin.yml fragments the wiring needs (commands/permissions), as YAML-compatible objects. */
  pluginYml?: { commands?: Record<string, unknown>; permissions?: Record<string, unknown> };
  retrieval: PatternRetrieval;
  /** Common APIs vs rare ones: the selector never auto-injects a "common" pattern. */
  frequency: "common" | "rare";
  files: PatternFile[];
  source: PatternSource;
  /** sha256 over the normalised metadata + files (excluding verification). */
  contentHash: string;
  /** Approximate tokens of the code block the model would see (chars / 3.5). */
  tokens: number;
  verification: VerificationRecord[];
  status: PatternStatus;
  /** Versions on which the CURRENT content verified fully. */
  verifiedOn: string[];
};

export type PatternLibrary = {
  game: string;
  /** Bumped by `library.js build` whenever any content changes (`lib-<date>.<n>`). */
  version: string;
  builtAt: string;
  /** Versions the build service supports for this game (MB_VERSIONS). */
  gameVersions: string[];
  patterns: LibraryPattern[];
  /** Pattern ids removed on request (opt-in withdrawn); never re-mined. */
  removed: { id: string; consentId?: string; at: string; reason: string }[];
};

/**
 * Explicit opt-in for turning a customer's build into library material (design; the listing/NxLabs
 * dialog owns the checkbox). Default is NO consent. One record per build; withdrawing sets revokedAt
 * and the next library build drops every pattern that cites this id.
 */
export type LibraryConsent = {
  id: string;
  userId: string;
  buildId: string;
  /** Version of the exact wording the owner agreed to (LIBRARY_CONSENT_WORDING). */
  wordingVersion: string;
  grantedAt: string;
  revokedAt: string | null;
};

export const LIBRARY_CONSENT_WORDING = {
  version: "draft-2026-10-08",
  text:
    "Let Cyrus learn reusable building blocks from this mod. Only small, generic pieces of code are kept, " +
    "never your mod's name, text, server or players. You can switch this off at any time; future builds " +
    "then stop using anything learned from it.",
} as const;

