mkdir -p /tank/dev-worktrees/cyrus-v6-library/services/modbuilder/library/minecraft/patterns && cd /tank/dev-worktrees/cyrus-v6-library/services/modbuilder/library && printf '# node-2 verification cache (JDK, Gradle, Paper jars, harness servers). Never commit.\n.cache/\n' > .gitignore && P=minecraft/patterns && mkdir -p $P/command-router && cat > $P/command-router/SubcommandRouter.java <<'EOF'
package __PKG__;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.PluginCommand;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * One plugin.yml command with subcommands: /name <sub> [args].
 * Each subcommand has its own permission, player-only flag, usage line and tab completion.
 * Wire: new SubcommandRouter(plugin, "name").sub("reload", "x.admin", false, "", ctx -> {...}).bind();
 * plugin.yml must declare the command "name" (the build checks it).
 */
public class SubcommandRouter implements CommandExecutor, TabCompleter {

    /** What a handler sees. args are the arguments AFTER the subcommand name. */
    public record Context(CommandSender sender, String label, String[] args) {
        public Player player() { return (Player) sender; }
        public String arg(int i, String def) { return i < args.length ? args[i] : def; }
        public void reply(Component c) { sender.sendMessage(c); }
        public void error(String text) { sender.sendMessage(Component.text(text, NamedTextColor.RED)); }
        /** Parses an int argument, replying with an error and returning null when it is not a number in range. */
        public Integer intArg(int i, int min, int max) {
            if (i >= args.length) { error("Missing a number."); return null; }
            try {
                int v = Integer.parseInt(args[i]);
                if (v < min || v > max) { error("Use a number from " + min + " to " + max + "."); return null; }
                return v;
            } catch (NumberFormatException e) { error("'" + args[i] + "' is not a number."); return null; }
        }
    }

    public interface Handler { void run(Context ctx); }
    public interface Completer { List<String> complete(Context ctx); }

    private record Sub(String name, String permission, boolean playerOnly, String usage, Handler handler, Completer completer) {}

    private final JavaPlugin plugin;
    private final String command;
    private final Map<String, Sub> subs = new LinkedHashMap<>();
    private Handler fallback;

    public SubcommandRouter(JavaPlugin plugin, String command) {
        this.plugin = plugin;
        this.command = command;
    }

    public SubcommandRouter sub(String name, String permission, boolean playerOnly, String usage, Handler handler) {
        return sub(name, permission, playerOnly, usage, handler, null);
    }

    public SubcommandRouter sub(String name, String permission, boolean playerOnly, String usage, Handler handler, Completer completer) {
        subs.put(name.toLowerCase(Locale.ROOT), new Sub(name.toLowerCase(Locale.ROOT), permission, playerOnly, usage, handler, completer));
        return this;
    }

    /** Runs when the command has no subcommand (default: the help list). */
    public SubcommandRouter fallback(Handler handler) { this.fallback = handler; return this; }

    /** Attaches executor + tab completer. Returns false (and logs) when plugin.yml lacks the command. */
    public boolean bind() {
        PluginCommand pc = plugin.getCommand(command);
        if (pc == null) {
            plugin.getLogger().severe("Command '" + command + "' is missing from plugin.yml");
            return false;
        }
        pc.setExecutor(this);
        pc.setTabCompleter(this);
        return true;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {
        if (args.length == 0) {
            if (fallback != null) fallback.run(new Context(sender, label, args));
            else help(sender, label);
            return true;
        }
        Sub sub = subs.get(args[0].toLowerCase(Locale.ROOT));
        if (sub == null) {
            sender.sendMessage(Component.text("Unknown subcommand. Try /" + label + " for help.", NamedTextColor.RED));
            return true;
        }
        if (sub.permission() != null && !sub.permission().isEmpty() && !sender.hasPermission(sub.permission())) {
            sender.sendMessage(Component.text("You do not have permission to do that.", NamedTextColor.RED));
            return true;
        }
        if (sub.playerOnly() && !(sender instanceof Player)) {
            sender.sendMessage(Component.text("Only players can use this.", NamedTextColor.RED));
            return true;
        }
        sub.handler().run(new Context(sender, label, Arrays.copyOfRange(args, 1, args.length)));
        return true;
    }

    public void help(CommandSender sender, String label) {
        sender.sendMessage(Component.text("/" + label + " commands:", NamedTextColor.GOLD));
        for (Sub s : subs.values()) {
            if (s.permission() != null && !s.permission().isEmpty() && !sender.hasPermission(s.permission())) continue;
            sender.sendMessage(Component.text(" /" + label + " " + s.name() + (s.usage().isEmpty() ? "" : " " + s.usage()), NamedTextColor.YELLOW));
        }
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command cmd, String alias, String[] args) {
        List<String> out = new ArrayList<>();
        if (args.length == 1) {
            String p = args[0].toLowerCase(Locale.ROOT);
            for (Sub s : subs.values()) {
                if (s.permission() != null && !s.permission().isEmpty() && !sender.hasPermission(s.permission())) continue;
                if (s.name().startsWith(p)) out.add(s.name());
            }
            return out;
        }
        Sub sub = subs.get(args[0].toLowerCase(Locale.ROOT));
        if (sub == null || sub.completer() == null) return out;
        if (sub.permission() != null && !sub.permission().isEmpty() && !sender.hasPermission(sub.permission())) return out;
        String[] rest = Arrays.copyOfRange(args, 1, args.length);
        String last = rest.length == 0 ? "" : rest[rest.length - 1].toLowerCase(Locale.ROOT);
        for (String s : sub.completer().complete(new Context(sender, alias, rest))) {
            if (s.toLowerCase(Locale.ROOT).startsWith(last)) out.add(s);
        }
        return out;
    }
}
