package __PKG__;

import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.ArrayList;
import java.util.List;

/**
 * Typed, validated view of config.yml. Read every value ONCE here (with a default and a range),
 * never scattered getConfig() calls. reload() re-reads the file and returns the problems found,
 * so a "/x reload" command can tell the operator exactly what was wrong.
 * Wire: settings = new Settings(this); settings.reload(); (after saveDefaultConfig()).
 * Extend: add a field + one line in load().
 */
public class Settings {

    private final JavaPlugin plugin;
    private final List<String> problems = new ArrayList<>();

    // ---- values (examples; rename to what the plugin needs) ----
    public int cooldownSeconds;
    public double multiplier;
    public boolean enabled;
    public String prefix;
    public List<String> messages;

    public Settings(JavaPlugin plugin) { this.plugin = plugin; }

    /** Re-reads config.yml. Returns human-readable problems (empty = all good). */
    public List<String> reload() {
        plugin.saveDefaultConfig();
        plugin.reloadConfig();
        problems.clear();
        load(plugin.getConfig());
        for (String p : problems) plugin.getLogger().warning("config.yml: " + p);
        return List.copyOf(problems);
    }

    private void load(FileConfiguration c) {
        enabled = c.getBoolean("enabled", true);
        cooldownSeconds = intIn(c, "cooldown-seconds", 30, 0, 86400);
        multiplier = doubleIn(c, "multiplier", 1.0, 0.0, 100.0);
        prefix = c.getString("prefix", "<gray>[<aqua>Server</aqua>]</gray> ");
        messages = c.getStringList("messages");
    }

    public int intIn(ConfigurationSection c, String path, int def, int min, int max) {
        if (!c.isSet(path)) return def;
        if (!c.isInt(path)) { problems.add(path + " must be a whole number; using " + def); return def; }
        int v = c.getInt(path);
        if (v < min || v > max) { int cl = Math.max(min, Math.min(max, v)); problems.add(path + " must be " + min + ".." + max + "; using " + cl); return cl; }
        return v;
    }

    public double doubleIn(ConfigurationSection c, String path, double def, double min, double max) {
        if (!c.isSet(path)) return def;
        if (!c.isDouble(path) && !c.isInt(path)) { problems.add(path + " must be a number; using " + def); return def; }
        double v = c.getDouble(path);
        if (Double.isNaN(v) || v < min || v > max) { double cl = Double.isNaN(v) ? def : Math.max(min, Math.min(max, v)); problems.add(path + " must be " + min + ".." + max + "; using " + cl); return cl; }
        return v;
    }

    /** A sub-section that may be missing: never null. */
    public static ConfigurationSection section(ConfigurationSection c, String path) {
        ConfigurationSection s = c.getConfigurationSection(path);
        return s != null ? s : c.createSection(path);
    }
}
