package __PKG__;

import org.bukkit.Bukkit;
import org.bukkit.configuration.InvalidConfigurationException;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Per-player YAML files under plugins/<Plugin>/players/<uuid>.yml.
 * - get(uuid) loads lazily (main thread) and caches; markDirty(uuid) after changing it.
 * - Autosave: every N seconds the dirty files are SERIALISED on the main thread (YamlConfiguration
 *   is not thread-safe) and WRITTEN off-thread, atomically (temp file + move), so a crash never
 *   leaves a half-written file.
 * - onDisable: call saveAllNow(): synchronous, because the scheduler refuses new tasks while the
 *   plugin disables and an async save would be lost.
 * - unload(uuid) on quit after saving, so the cache does not grow forever.
 */
public class PlayerDataStore {

    private final JavaPlugin plugin;
    private final File dir;
    private final Map<UUID, YamlConfiguration> cache = new HashMap<>();
    private final Set<UUID> dirty = new HashSet<>();
    private BukkitTask autosave;

    public PlayerDataStore(JavaPlugin plugin, String folder) {
        this.plugin = plugin;
        this.dir = new File(plugin.getDataFolder(), folder);
        if (!dir.isDirectory() && !dir.mkdirs()) plugin.getLogger().warning("Could not create " + dir);
    }

    public YamlConfiguration get(UUID id) {
        return cache.computeIfAbsent(id, k -> {
            YamlConfiguration y = new YamlConfiguration();
            File f = file(k);
            if (f.isFile()) {
                try { y.load(f); } catch (IOException | InvalidConfigurationException e) {
                    plugin.getLogger().warning("Bad data file " + f.getName() + " (" + e.getMessage() + "), starting empty");
                }
            }
            return y;
        });
    }

    public void markDirty(UUID id) { dirty.add(id); }

    public boolean isLoaded(UUID id) { return cache.containsKey(id); }

    /** Starts the periodic async writer. */
    public void startAutosave(int seconds) {
        stopAutosave();
        long period = Math.max(20L, seconds * 20L);
        autosave = Bukkit.getScheduler().runTaskTimer(plugin, this::flushAsync, period, period);
    }

    public void stopAutosave() { if (autosave != null) { autosave.cancel(); autosave = null; } }

    /** Main thread: snapshot dirty players to strings, then write them off-thread. */
    public void flushAsync() {
        if (dirty.isEmpty()) return;
        Map<UUID, String> snap = new HashMap<>();
        for (UUID id : dirty) { YamlConfiguration y = cache.get(id); if (y != null) snap.put(id, y.saveToString()); }
        dirty.clear();
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> snap.forEach(this::write));
    }

    /** Synchronous save of everything dirty. Use in onDisable and before unload(). */
    public void saveAllNow() {
        for (UUID id : dirty) { YamlConfiguration y = cache.get(id); if (y != null) write(id, y.saveToString()); }
        dirty.clear();
    }

    public void saveNow(UUID id) {
        YamlConfiguration y = cache.get(id);
        if (y != null && dirty.remove(id)) write(id, y.saveToString());
    }

    /** Save (if dirty) and drop from memory, e.g. on PlayerQuitEvent. */
    public void unload(UUID id) { saveNow(id); cache.remove(id); }

    private File file(UUID id) { return new File(dir, id + ".yml"); }

    private void write(UUID id, String yaml) {
        Path target = file(id).toPath();
        Path tmp = target.resolveSibling(target.getFileName() + ".tmp");
        try {
            Files.writeString(tmp, yaml, StandardCharsets.UTF_8);
            try { Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE); }
            catch (IOException e) { Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING); }
        } catch (IOException e) {
            plugin.getLogger().severe("Could not save " + target.getFileName() + ": " + e.getMessage());
        }
    }
}
