package __PKG__;

import org.bukkit.entity.Player;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Per-player cooldowns for one action, keyed by UUID (never by Player: Player objects go stale
 * after a relog). Uses wall-clock millis so it survives lag spikes. Thread-safe.
 * Wire: Cooldowns heal = new Cooldowns(30_000, "x.cooldown.bypass");
 *       long left = heal.tryUse(player); if (left > 0) { tell "wait " + Cooldowns.format(left); return; }
 * Call clear(uuid) on quit if the cooldown should not outlive the session.
 */
public class Cooldowns {

    private final Map<UUID, Long> until = new ConcurrentHashMap<>();
    private volatile long durationMs;
    private final String bypassPermission;

    public Cooldowns(long durationMs, String bypassPermission) {
        this.durationMs = durationMs;
        this.bypassPermission = bypassPermission;
    }

    public void setDuration(long ms) { this.durationMs = Math.max(0, ms); }

    /** 0 = allowed now (and the cooldown starts); otherwise the millis left. */
    public long tryUse(Player player) {
        if (bypassPermission != null && !bypassPermission.isEmpty() && player.hasPermission(bypassPermission)) return 0;
        return tryUse(player.getUniqueId());
    }

    public long tryUse(UUID id) {
        long now = System.currentTimeMillis();
        long[] left = {0};
        until.compute(id, (k, end) -> {
            if (end != null && end > now) { left[0] = end - now; return end; }
            return now + durationMs;
        });
        return left[0];
    }

    public long remaining(UUID id) {
        Long end = until.get(id);
        return end == null ? 0 : Math.max(0, end - System.currentTimeMillis());
    }

    public void reset(UUID id) { until.remove(id); }

    public void clear(UUID id) { until.remove(id); }

    /** Drops expired entries (call from a slow timer if many players pass through). */
    public void prune() { long now = System.currentTimeMillis(); until.values().removeIf(end -> end <= now); }

    /** 75_000 -> "1m 15s", 4_200 -> "5s" (rounded up). */
    public static String format(long ms) {
        long s = (ms + 999) / 1000;
        if (s >= 3600) return (s / 3600) + "h " + ((s % 3600) / 60) + "m";
        if (s >= 60) return (s / 60) + "m " + (s % 60) + "s";
        return s + "s";
    }
}
