package __PKG__;

import org.bukkit.Bukkit;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

/**
 * A repeating main-thread task you can start, stop and restart (e.g. after /x reload changes the
 * interval) without ever running two copies. Exceptions inside the body are logged and do not
 * kill the timer. Uses a plain Runnable with the scheduler (passing a BukkitRunnable to
 * runTaskTimer throws at runtime).
 * Wire: broadcaster = new ManagedTask(this, "broadcast", () -> {...}); broadcaster.start(20L * secs);
 *       onDisable: broadcaster.stop();
 */
public class ManagedTask {

    private final JavaPlugin plugin;
    private final String name;
    private final Runnable body;
    private BukkitTask task;
    private long periodTicks;

    public ManagedTask(JavaPlugin plugin, String name, Runnable body) {
        this.plugin = plugin;
        this.name = name;
        this.body = body;
    }

    /** (Re)starts with the given period in ticks (20 = 1 second); the first run is one period from now. */
    public void start(long periodTicks) { start(periodTicks, periodTicks); }

    public void start(long delayTicks, long periodTicks) {
        stop();
        this.periodTicks = Math.max(1L, periodTicks);
        task = Bukkit.getScheduler().runTaskTimer(plugin, this::safeRun, Math.max(0L, delayTicks), this.periodTicks);
    }

    public void stop() {
        if (task != null) { task.cancel(); task = null; }
    }

    public boolean isRunning() { return task != null && !task.isCancelled(); }

    public long periodTicks() { return periodTicks; }

    private void safeRun() {
        try { body.run(); }
        catch (Throwable t) { plugin.getLogger().warning("Task '" + name + "' failed: " + t); }
    }
}
