 * A chest menu identified by its InventoryHolder (never by title: players can rename chests).
 * Buttons are slot -> action. MenuListener cancels EVERY click and drag while a Menu is the top
 * inventory (including shift-click, number keys, double-click collect and clicks in the player's
 * own inventory), which closes the classic item-duplication holes.
 * Wire: register MenuListener once; then
 *   Menu m = new Menu(27, Component.text("Warps")); m.button(10, item, e -> ...); m.open(player);
 */
public class Menu implements InventoryHolder {

    private final Inventory inventory;
    private final Map<Integer, Consumer<InventoryClickEvent>> actions = new HashMap<>();
    private Consumer<Player> onClose;

    /** size: 9..54, multiple of 9. */
    public Menu(int size, Component title) {
        int s = Math.max(9, Math.min(54, (size + 8) / 9 * 9));
        this.inventory = Bukkit.createInventory(this, s, title);
    }

    @Override
    public Inventory getInventory() { return inventory; }

    public Menu button(int slot, ItemStack icon, Consumer<InventoryClickEvent> action) {
        if (slot < 0 || slot >= inventory.getSize()) throw new IllegalArgumentException("slot " + slot + " outside menu");
        inventory.setItem(slot, icon);
        if (action != null) actions.put(slot, action); else actions.remove(slot);
        return this;
    }

    public Menu fill(ItemStack filler) {
        for (int i = 0; i < inventory.getSize(); i++) if (inventory.getItem(i) == null) inventory.setItem(i, filler);
        return this;
    }

    public Menu clear() { inventory.clear(); actions.clear(); return this; }

    public Menu onClose(Consumer<Player> callback) { this.onClose = callback; return this; }

    public void open(Player player) { player.openInventory(inventory); }

    /** Called by MenuListener for clicks inside the menu's own slots. */
    void handle(InventoryClickEvent e) {
        Consumer<InventoryClickEvent> a = actions.get(e.getRawSlot());
        if (a != null) a.accept(e);
    }

    void closed(Player p) { if (onClose != null) onClose.accept(p); }

    public boolean hasAction(int slot) { return actions.containsKey(slot); }
}
