package __PKG__;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.inventory.ItemStack;

import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Function;

/**
 * A list of any length shown over pages of a 54-slot Menu: 45 entries per page, bottom row has
 * previous / page number / next. Built on the chest-menu pattern (Menu + MenuListener).
 * Wire: new PagedMenu<>(title, warps, w -> icon(w), (w, e) -> teleport(w)).open(player, 0);
 */
public class PagedMenu<T> {

    public static final int PER_PAGE = 45;

    private final Component title;
    private final List<T> entries;
    private final Function<T, ItemStack> icon;
    private final BiConsumer<T, InventoryClickEvent> onPick;

    public PagedMenu(Component title, List<T> entries, Function<T, ItemStack> icon, BiConsumer<T, InventoryClickEvent> onPick) {
        this.title = title;
        this.entries = List.copyOf(entries);
        this.icon = icon;
        this.onPick = onPick;
    }

    public int pages() { return Math.max(1, (entries.size() + PER_PAGE - 1) / PER_PAGE); }

    /** Builds the Menu for a page (0-based, clamped). */
    public Menu build(int page) {
        int p = Math.max(0, Math.min(pages() - 1, page));
        Menu m = new Menu(54, title.append(Component.text(" (" + (p + 1) + "/" + pages() + ")", NamedTextColor.GRAY)));
        int from = p * PER_PAGE;
        for (int i = 0; i < PER_PAGE && from + i < entries.size(); i++) {
            T t = entries.get(from + i);
            m.button(i, icon.apply(t), e -> onPick.accept(t, e));
        }
        if (p > 0) m.button(45, named(Material.ARROW, "Previous page"), e -> { if (e.getWhoClicked() instanceof Player pl) open(pl, p - 1); });
        m.button(49, named(Material.PAPER, "Page " + (p + 1) + " of " + pages()), null);
        if (p < pages() - 1) m.button(53, named(Material.ARROW, "Next page"), e -> { if (e.getWhoClicked() instanceof Player pl) open(pl, p + 1); });
        return m;
    }

    public void open(Player player, int page) { build(page).open(player); }

    private static ItemStack named(Material mat, String name) {
        ItemStack it = new ItemStack(mat);
        it.editMeta(meta -> meta.displayName(Component.text(name, NamedTextColor.YELLOW).decoration(TextDecoration.ITALIC, false)));
        return it;
    }
}
