package __PKG__;

import net.kyori.adventure.bossbar.BossBar;
import net.kyori.adventure.text.Component;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

import java.util.HashSet;
import java.util.Set;
import java.util.UUID;
import java.util.function.IntConsumer;
import java.util.function.IntFunction;

/**
 * A boss-bar countdown that empties over N seconds. Tracks its own viewers by UUID
 * (BossBar.viewers() returns BossBarViewer, not players), keeps progress inside 0..1, and always
 * hides itself from everyone on finish, cancel and plugin disable.
 * Wire: Countdown c = new Countdown(plugin, 10, s -> Component.text("Starting in " + s), s -> tick(s), () -> go());
 *       c.showTo(player) for each viewer (or c.showToAll()); c.start(); onDisable: c.cancel().
 */
public class Countdown {

    private final JavaPlugin plugin;
    private final int seconds;
    private final IntFunction<Component> title;
    private final IntConsumer onSecond;
    private final Runnable onFinish;
    private final BossBar bar;
    private final Set<UUID> viewers = new HashSet<>();
    private BukkitTask task;
    private int left;

    public Countdown(JavaPlugin plugin, int seconds, IntFunction<Component> title, IntConsumer onSecond, Runnable onFinish) {
        this.plugin = plugin;
        this.seconds = Math.max(1, seconds);
        this.title = title;
        this.onSecond = onSecond;
        this.onFinish = onFinish;
        this.bar = BossBar.bossBar(title.apply(this.seconds), 1.0f, BossBar.Color.RED, BossBar.Overlay.PROGRESS);
    }

    public BossBar bar() { return bar; }

    public void showTo(Player p) { if (viewers.add(p.getUniqueId())) p.showBossBar(bar); }

    public void showToAll() { for (Player p : Bukkit.getOnlinePlayers()) showTo(p); }

    public void hideFrom(Player p) { if (viewers.remove(p.getUniqueId())) p.hideBossBar(bar); }

    public boolean isRunning() { return task != null; }

    public int secondsLeft() { return left; }

    public void start() {
        cancel();
        left = seconds;
        update();
        task = Bukkit.getScheduler().runTaskTimer(plugin, () -> {
            left--;
            if (left <= 0) { stopAndHide(); if (onFinish != null) onFinish.run(); return; }
            update();
            if (onSecond != null) onSecond.accept(left);
        }, 20L, 20L);
    }

    /** Stops without running onFinish. Safe to call any time (also in onDisable). */
    public void cancel() { stopAndHide(); }

    private void update() {
        bar.name(title.apply(left));
        bar.progress(Math.max(0f, Math.min(1f, left / (float) seconds)));
    }

    private void stopAndHide() {
        if (task != null) { task.cancel(); task = null; }
        for (UUID id : viewers) { Player p = Bukkit.getPlayer(id); if (p != null) p.hideBossBar(bar); }
        viewers.clear();
    }
}
