package __PKG__;

import net.kyori.adventure.audience.Audience;
import net.kyori.adventure.key.InvalidKeyException;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.sound.Sound;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.title.Title;

import java.time.Duration;
import java.util.Locale;

/**
 * Titles, action bars and sounds through Adventure, so the same code works on every 1.21.x:
 * sounds are addressed by their key ("entity.player.levelup"), not by org.bukkit.Sound constants
 * (an enum on 1.21.1, an interface on 1.21.4+). Works for one player, Bukkit.getServer() (everyone)
 * or any Audience.
 */
public final class Announce {

    private Announce() {}

    public static void title(Audience to, Component main, Component sub, int fadeInTicks, int stayTicks, int fadeOutTicks) {
        to.showTitle(Title.title(main, sub, Title.Times.times(ticks(fadeInTicks), ticks(stayTicks), ticks(fadeOutTicks))));
    }

    public static void title(Audience to, Component main, Component sub) { title(to, main, sub, 10, 60, 10); }

    public static void actionBar(Audience to, Component text) { to.sendActionBar(text); }

    /**
     * Plays a sound by key, e.g. "entity.player.levelup" or "minecraft:block.note_block.pling".
     * Returns false (and plays nothing) for a malformed key, so config typos never throw.
     */
    public static boolean sound(Audience to, String key, float volume, float pitch) {
        Key k = parseKey(key);
        if (k == null) return false;
        to.playSound(Sound.sound(k, Sound.Source.MASTER, volume, pitch));
        return true;
    }

    /** "ENTITY_PLAYER_LEVELUP" (old enum style) and "entity.player.levelup" both become a key. */
    public static Key parseKey(String raw) {
        if (raw == null || raw.isBlank()) return null;
        String s = raw.trim().toLowerCase(Locale.ROOT);
        if (!s.contains(".") && !s.contains(":")) s = s.replace('_', '.');
        try { return s.contains(":") ? Key.key(s) : Key.key("minecraft", s); }
        catch (InvalidKeyException e) { return null; }
    }

    private static Duration ticks(int t) { return Duration.ofMillis(Math.max(0, t) * 50L); }
}
