package __PKG__;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.minimessage.MiniMessage;
import net.kyori.adventure.text.minimessage.tag.resolver.Placeholder;
import net.kyori.adventure.text.minimessage.tag.resolver.TagResolver;
import net.kyori.adventure.text.serializer.legacy.LegacyComponentSerializer;
import org.bukkit.configuration.ConfigurationSection;

import java.util.HashMap;
import java.util.Map;

/**
 * Player-facing text from config.yml "messages:" with MiniMessage (<gold>, <bold>...) and named
 * placeholders. Player-typed values are inserted as UNPARSED text, so a player called
 * "<red>Admin" cannot inject formatting. Old "&a" colour codes are still accepted.
 * Wire: messages = new Messages(getConfig().getConfigurationSection("messages"), "prefix");
 *       player.sendMessage(messages.get("healed", "player", player.getName()));
 */
public class Messages {

    private static final MiniMessage MM = MiniMessage.miniMessage();
    private final Map<String, String> raw = new HashMap<>();
    private final String prefixKey;

    public Messages(ConfigurationSection section, String prefixKey) {
        this.prefixKey = prefixKey;
        if (section != null) for (String k : section.getKeys(true)) if (section.isString(k)) raw.put(k, section.getString(k));
    }

    /** get("key", "name1", value1, "name2", value2...). Missing keys render as the key itself. */
    public Component get(String key, String... pairs) {
        String text = raw.getOrDefault(key, key);
        String prefix = prefixKey == null ? "" : raw.getOrDefault(prefixKey, "");
        return render(prefix + text, pairs);
    }

    /** Without the prefix (titles, item names, lore). */
    public Component plain(String key, String... pairs) { return render(raw.getOrDefault(key, key), pairs); }

    public static Component render(String text, String... pairs) {
        if (text.indexOf('&') >= 0 && text.indexOf('<') < 0) {
            return LegacyComponentSerializer.legacyAmpersand().deserialize(fill(text, pairs));
        }
        TagResolver.Builder b = TagResolver.builder();
        for (int i = 0; i + 1 < pairs.length; i += 2) b.resolver(Placeholder.unparsed(pairs[i], pairs[i + 1] == null ? "" : pairs[i + 1]));
        return MM.deserialize(text, b.build());
    }

    private static String fill(String text, String... pairs) {
        String out = text;
        for (int i = 0; i + 1 < pairs.length; i += 2) out = out.replace("<" + pairs[i] + ">", pairs[i + 1] == null ? "" : pairs[i + 1]);
        return out;
    }
}
