package __PKG__;

import io.papermc.paper.scoreboard.numbers.NumberFormat;
import net.kyori.adventure.text.Component;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.scoreboard.Criteria;
import org.bukkit.scoreboard.DisplaySlot;
import org.bukkit.scoreboard.Objective;
import org.bukkit.scoreboard.Score;
import org.bukkit.scoreboard.Scoreboard;

import java.util.ArrayList;
import java.util.List;

/**
 * One sidebar per player (each player gets their own Scoreboard so lines can differ).
 * Lines are Components set as the score's display name on fixed hidden entries, so changing a
 * line never flickers or leaves a stale duplicate, and the red score numbers are hidden.
 * Max 15 lines. Create once per player (on join), call setLines(...) from a timer, remove() on quit.
 */
public class Sidebar {

    public static final int MAX_LINES = 15;

    private final Scoreboard board;
    private final Objective objective;
    private final List<String> entries = new ArrayList<>();
    private final Player player;

    public Sidebar(Player player, Component title) {
        this.player = player;
        this.board = Bukkit.getScoreboardManager().getNewScoreboard();
        this.objective = board.registerNewObjective("sidebar", Criteria.DUMMY, title);
        this.objective.setDisplaySlot(DisplaySlot.SIDEBAR);
        this.objective.numberFormat(NumberFormat.blank());
        for (int i = 0; i < MAX_LINES; i++) entries.add("line" + i);
        if (player != null) player.setScoreboard(board);
    }

    public void title(Component title) { objective.displayName(title); }

    /** Top to bottom. Extra lines beyond 15 are ignored; missing lines are removed. */
    public void setLines(List<Component> lines) {
        int n = Math.min(MAX_LINES, lines.size());
        for (int i = 0; i < MAX_LINES; i++) {
            String entry = entries.get(i);
            if (i < n) {
                Score s = objective.getScore(entry);
                s.setScore(n - i);
                s.customName(lines.get(i));
            } else if (board.getEntries().contains(entry)) {
                board.resetScores(entry);
            }
        }
    }

    public Scoreboard board() { return board; }

    /** Gives the player the server's main scoreboard back. */
    public void remove() {
        if (player != null && player.isOnline()) player.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());
        objective.unregister();
    }
}
