package __PKG__;

import org.bukkit.NamespacedKey;
import org.bukkit.entity.Entity;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Identify items and entities by a hidden PersistentDataContainer tag, never by name or lore
 * (players can rename items in an anvil; lore is shared with other plugins). The tag survives
 * renames, restarts and being moved between inventories.
 * Uses getItemMeta/setItemMeta (works on every 1.21.x; editPersistentDataContainer is newer).
 * Wire: ItemTag soulbound = new ItemTag(plugin, "soulbound");
 *       soulbound.mark(item, "1"); if (soulbound.has(item)) ...; soulbound.value(item)
 */
public class ItemTag {

    private final NamespacedKey key;

    public ItemTag(JavaPlugin plugin, String name) { this.key = new NamespacedKey(plugin, name); }

    public NamespacedKey key() { return key; }

    /** Tags the item with a string value (e.g. a custom item id). Returns false for air / no meta. */
    public boolean mark(ItemStack item, String value) {
        if (item == null || item.getType().isAir()) return false;
        ItemMeta meta = item.getItemMeta();
        if (meta == null) return false;
        meta.getPersistentDataContainer().set(key, PersistentDataType.STRING, value);
        item.setItemMeta(meta);
        return true;
    }

    public boolean unmark(ItemStack item) {
        if (item == null || item.getType().isAir()) return false;
        ItemMeta meta = item.getItemMeta();
        if (meta == null || !meta.getPersistentDataContainer().has(key, PersistentDataType.STRING)) return false;
        meta.getPersistentDataContainer().remove(key);
        item.setItemMeta(meta);
        return true;
    }

    public boolean has(ItemStack item) { return value(item) != null; }

    /** The stored value or null (null-safe for air and items without meta). */
    public String value(ItemStack item) {
        if (item == null || item.getType().isAir() || !item.hasItemMeta()) return null;
        ItemMeta meta = item.getItemMeta();
        return meta == null ? null : meta.getPersistentDataContainer().get(key, PersistentDataType.STRING);
    }

    public void mark(Entity entity, String value) { entity.getPersistentDataContainer().set(key, PersistentDataType.STRING, value); }

    public String value(Entity entity) {
        PersistentDataContainer pdc = entity.getPersistentDataContainer();
        return pdc.get(key, PersistentDataType.STRING);
    }
}
