cat > item-builder/ItemBuilder.java <<'EOF'
package __PKG__;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Material;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.Item;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemFlag;
import org.bukkit.inventory.ItemStack;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

/**
 * Builds display items and custom gear with Components (names are not italic by default),
 * enchantments (unsafe levels allowed), glint, unbreakable, hidden flags. give() puts the item in
 * the inventory and drops whatever did not fit at the player's feet instead of losing it.
 */
public class ItemBuilder {

    private final ItemStack item;
    private Component name;
    private final List<Component> lore = new ArrayList<>();
    private boolean glint, unbreakable;
    private final List<ItemFlag> flags = new ArrayList<>();

    public ItemBuilder(Material material, int amount) {
        this.item = new ItemStack(material, Math.max(1, Math.min(material.getMaxStackSize(), amount)));
    }

    public static ItemBuilder of(Material material) { return new ItemBuilder(material, 1); }

    public ItemBuilder name(Component c) { this.name = c.decorationIfAbsent(TextDecoration.ITALIC, TextDecoration.State.FALSE); return this; }

    public ItemBuilder lore(Component line) { lore.add(line.decorationIfAbsent(TextDecoration.ITALIC, TextDecoration.State.FALSE)); return this; }

    public ItemBuilder enchant(Enchantment e, int level) { item.addUnsafeEnchantment(e, level); return this; }

    public ItemBuilder glint() { this.glint = true; return this; }

    public ItemBuilder unbreakable() { this.unbreakable = true; return this; }

    public ItemBuilder hide(ItemFlag... f) { flags.addAll(List.of(f)); return this; }

    public ItemStack build() {
        ItemStack out = item.clone();
        out.editMeta(meta -> {
            if (name != null) meta.displayName(name);
            if (!lore.isEmpty()) meta.lore(lore);
            if (glint) meta.setEnchantmentGlintOverride(true);
            if (unbreakable) meta.setUnbreakable(true);
            if (!flags.isEmpty()) meta.addItemFlags(flags.toArray(new ItemFlag[0]));
        });
        return out;
    }

    /** Adds to the inventory; leftovers drop at the player's feet. Returns how many were dropped. */
    public static int give(Player player, ItemStack stack) {
        HashMap<Integer, ItemStack> left = player.getInventory().addItem(stack);
        int dropped = 0;
        for (ItemStack rest : left.values()) {
            Item drop = player.getWorld().dropItemNaturally(player.getLocation(), rest);
            drop.setOwner(player.getUniqueId());
            dropped += rest.getAmount();
        }
        return dropped;
    }
}
