cat > shaped-recipe/Recipes.java <<'EOF'
package __PKG__;

import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.ShapedRecipe;
import org.bukkit.inventory.ShapelessRecipe;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Registers keyed crafting recipes, shows them in every player's recipe book (on join, and to
 * players already online, e.g. after /reload), and removes them again in onDisable so a plugin
 * update never leaves a stale or duplicate recipe ("duplicate recipe ignored" on re-enable).
 * Wire: recipes = new Recipes(this); recipes.shaped("super_pickaxe", result, new String[]{"DDD"," S "," S "},
 *        Map.of('D', Material.DIAMOND_BLOCK, 'S', Material.STICK)); onDisable: recipes.unregisterAll();
 */
public class Recipes implements Listener {

    private final JavaPlugin plugin;
    private final List<NamespacedKey> keys = new ArrayList<>();

    public Recipes(JavaPlugin plugin) {
        this.plugin = plugin;
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
    }

    public NamespacedKey shaped(String id, ItemStack result, String[] shape, Map<Character, Material> ingredients) {
        NamespacedKey key = new NamespacedKey(plugin, id);
        Bukkit.removeRecipe(key);
        ShapedRecipe r = new ShapedRecipe(key, result);
        r.shape(shape);
        ingredients.forEach(r::setIngredient);
        return add(key, r);
    }

    public NamespacedKey shapeless(String id, ItemStack result, List<Material> ingredients) {
        NamespacedKey key = new NamespacedKey(plugin, id);
        Bukkit.removeRecipe(key);
        ShapelessRecipe r = new ShapelessRecipe(key, result);
        for (Material m : ingredients) r.addIngredient(m);
        return add(key, r);
    }

    private NamespacedKey add(NamespacedKey key, org.bukkit.inventory.Recipe r) {
        if (!Bukkit.addRecipe(r)) plugin.getLogger().warning("Recipe " + key + " was not added");
        keys.add(key);
        for (Player p : Bukkit.getOnlinePlayers()) p.discoverRecipe(key);
        return key;
    }

    public List<NamespacedKey> keys() { return List.copyOf(keys); }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) { e.getPlayer().discoverRecipes(keys); }

    public void unregisterAll() {
        for (NamespacedKey k : keys) Bukkit.removeRecipe(k);
        keys.clear();
    }
}
