package __PKG__;

import org.bukkit.NamespacedKey;
import org.bukkit.Registry;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.attribute.AttributeModifier;
import org.bukkit.entity.LivingEntity;

import java.util.Locale;

/**
 * Attributes (scale, max health, speed, jump...) that work on EVERY 1.21.x:
 *  - 1.21.1: Attribute is an enum, keys are "generic.scale", "player.block_break_speed"
 *  - 1.21.4+: Attribute is an interface, keys are "scale", "block_break_speed"
 * byName("scale") tries the plain key first, then the prefixed one, so no version-specific
 * constant (GENERIC_SCALE vs SCALE) ever appears in the code. Modifiers are keyed, so applying
 * the same one twice replaces it instead of stacking.
 */
public final class Attributes {

    private Attributes() {}

    /** "scale", "max_health", "movement_speed", "jump_strength", "attack_damage"... or null. */
    public static Attribute byName(String name) {
        String n = name.toLowerCase(Locale.ROOT).replace(' ', '_');
        if (n.startsWith("minecraft:")) n = n.substring(10);
        for (String candidate : new String[]{n, "generic." + n, "player." + n, "zombie." + n}) {
            Attribute a = Registry.ATTRIBUTE.get(NamespacedKey.minecraft(candidate));
            if (a != null) return a;
        }
        return null;
    }

    /** Sets (replaces) a keyed modifier. Returns false when the entity has no such attribute. */
    public static boolean setModifier(LivingEntity e, Attribute attr, NamespacedKey key, double amount, AttributeModifier.Operation op) {
        if (attr == null) return false;
        AttributeInstance inst = e.getAttribute(attr);
        if (inst == null) return false;
        inst.removeModifier(key);
        if (amount != 0) inst.addModifier(new AttributeModifier(key, amount, op));
        return true;
    }

    public static void clearModifier(LivingEntity e, Attribute attr, NamespacedKey key) {
        if (attr == null) return;
        AttributeInstance inst = e.getAttribute(attr);
        if (inst != null) inst.removeModifier(key);
    }

    /** Sets the base value (e.g. max health 100) and tops health up to the new maximum if asked. */
    public static boolean setBase(LivingEntity e, Attribute attr, double value) {
        if (attr == null) return false;
        AttributeInstance inst = e.getAttribute(attr);
        if (inst == null) return false;
        inst.setBaseValue(value);
        return true;
    }

    /** Current value (base + modifiers) or the fallback. */
    public static double value(LivingEntity e, Attribute attr, double fallback) {
        if (attr == null) return fallback;
        AttributeInstance inst = e.getAttribute(attr);
        return inst == null ? fallback : inst.getValue();
    }
}
