package __PKG__;

import org.bukkit.NamespacedKey;
import org.bukkit.Registry;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;

/**
 * Potion effects from config strings: "speed 2 30s", "strength 1 10", "night_vision 1 infinite".
 * Level is 1-based (what players see); duration in seconds ("30", "30s", "2m", "infinite").
 * Effect names are registry keys (speed, strength, jump_boost, slowness...), looked up through
 * Registry.EFFECT, so the deprecated getByName and old names (INCREASE_DAMAGE, SLOW) are never used.
 */
public final class PotionSpec {

    private PotionSpec() {}

    public static PotionEffectType type(String name) {
        String n = name.toLowerCase(Locale.ROOT).trim();
        if (n.startsWith("minecraft:")) n = n.substring(10);
        return Registry.EFFECT.get(NamespacedKey.minecraft(n));
    }

    /** Parses one spec; returns null (and reports why) when it is invalid. */
    public static PotionEffect parse(String spec, Consumer<String> problem) {
        String[] p = spec.trim().split("[\\s:]+");
        if (p.length == 0 || p[0].isEmpty()) { problem.accept("empty effect"); return null; }
        PotionEffectType t = type(p[0]);
        if (t == null) { problem.accept("unknown effect '" + p[0] + "'"); return null; }
        int level = 1;
        if (p.length > 1) {
            try { level = Integer.parseInt(p[1]); } catch (NumberFormatException e) { problem.accept("bad level in '" + spec + "'"); return null; }
        }
        level = Math.max(1, Math.min(255, level));
        int ticks = 30 * 20;
        if (p.length > 2) {
            String d = p[2].toLowerCase(Locale.ROOT);
            if (d.equals("infinite") || d.equals("forever")) ticks = PotionEffect.INFINITE_DURATION;
            else {
                try {
                    int mult = d.endsWith("m") ? 60 : 1;
                    int n = Integer.parseInt(d.replaceAll("[sm]$", ""));
                    ticks = Math.max(1, n * mult * 20);
                } catch (NumberFormatException e) { problem.accept("bad duration in '" + spec + "'"); return null; }
            }
        }
        return new PotionEffect(t, ticks, level - 1, false, true, true);
    }

    public static List<PotionEffect> parseAll(List<String> specs, Consumer<String> problem) {
        List<PotionEffect> out = new ArrayList<>();
        for (String s : specs) { PotionEffect e = parse(s, problem); if (e != null) out.add(e); }
        return out;
    }
}
