package __PKG__;

import net.kyori.adventure.text.Component;
import org.bukkit.Location;
import org.bukkit.NamespacedKey;
import org.bukkit.Registry;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Mob;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;

/**
 * Named custom mobs: spawned already configured (world.spawn with a consumer, so players never see
 * a default mob for a tick), tagged in PDC with their type id, with health/speed/size set through
 * attributes looked up by key (works on 1.21.1 and 1.21.4+), custom drops replacing vanilla ones.
 * Wire: mobs = new CustomMobs(plugin); mobs.define(new CustomMobs.Type("giant", Zombie.class, name, 100, 1.3, 3.0, drops, z -> {}));
 *       mobs.spawn("giant", location);
 */
public class CustomMobs implements Listener {

    public record Type(String id, Class<? extends Mob> entity, Component name, double maxHealth, double speedMultiplier,
                       double scale, List<ItemStack> drops, Consumer<Mob> extra) {}

    private final NamespacedKey key;
    private final Map<String, Type> types = new HashMap<>();

    public CustomMobs(JavaPlugin plugin) {
        this.key = new NamespacedKey(plugin, "mob_type");
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
    }

    public void define(Type t) { types.put(t.id().toLowerCase(Locale.ROOT), t); }

    public Mob spawn(String id, Location at) {
        Type t = types.get(id.toLowerCase(Locale.ROOT));
        if (t == null || at.getWorld() == null) return null;
        return at.getWorld().spawn(at, t.entity(), m -> {
            m.getPersistentDataContainer().set(key, PersistentDataType.STRING, t.id());
            if (t.name() != null) { m.customName(t.name()); m.setCustomNameVisible(true); }
            setBase(m, "max_health", t.maxHealth());
            if (t.maxHealth() > 0) m.setHealth(t.maxHealth());
            AttributeInstance speed = instance(m, "movement_speed");
            if (speed != null && t.speedMultiplier() > 0) speed.setBaseValue(speed.getBaseValue() * t.speedMultiplier());
            setBase(m, "scale", t.scale());
            m.setRemoveWhenFarAway(false);
            if (t.extra() != null) t.extra().accept(m);
        });
    }

    /** The custom type id of an entity, or null for normal mobs. */
    public String typeOf(LivingEntity e) { return e.getPersistentDataContainer().get(key, PersistentDataType.STRING); }

    @EventHandler
    public void onDeath(EntityDeathEvent e) {
        String id = typeOf(e.getEntity());
        if (id == null) return;
        Type t = types.get(id);
        if (t == null || t.drops() == null) return;
        e.getDrops().clear();
        for (ItemStack d : t.drops()) e.getDrops().add(d.clone());
    }

    private static AttributeInstance instance(LivingEntity m, String name) {
        for (String k : new String[]{name, "generic." + name}) {
            Attribute a = Registry.ATTRIBUTE.get(NamespacedKey.minecraft(k));
            if (a != null) return m.getAttribute(a);
        }
        return null;
    }

    private static void setBase(LivingEntity m, String name, double value) {
        if (value <= 0) return;
        AttributeInstance inst = instance(m, name);
        if (inst != null) inst.setBaseValue(value);
    }
}
