package __PKG__;

import org.bukkit.Chunk;
import org.bukkit.Location;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Chunk claims: owner + trusted players per chunk, keyed by world name + chunk x/z
 * (never by Chunk objects, which unload). Pure data; ClaimProtection enforces it.
 * Persist with save(yaml)/load(yaml) through the player-data-store or a single claims.yml.
 */
public class ClaimStore {

    public record Claim(UUID owner, Set<UUID> trusted) {}

    private final Map<String, Claim> claims = new HashMap<>();

    public static String key(String world, int cx, int cz) { return world + ";" + cx + ";" + cz; }

    public static String key(Chunk c) { return key(c.getWorld().getName(), c.getX(), c.getZ()); }

    public static String key(Location l) {
        return key(l.getWorld().getName(), l.getBlockX() >> 4, l.getBlockZ() >> 4);
    }

    public Claim at(Location l) { return l.getWorld() == null ? null : claims.get(key(l)); }

    public Claim get(String key) { return claims.get(key); }

    /** False if already claimed or the owner reached max. */
    public boolean claim(String key, UUID owner, int max) {
        if (claims.containsKey(key) || countOwned(owner) >= max) return false;
        claims.put(key, new Claim(owner, new HashSet<>()));
        return true;
    }

    public boolean unclaim(String key, UUID by) {
        Claim c = claims.get(key);
        if (c == null || !c.owner().equals(by)) return false;
        claims.remove(key);
        return true;
    }

    public int countOwned(UUID owner) {
        int n = 0;
        for (Claim c : claims.values()) if (c.owner().equals(owner)) n++;
        return n;
    }

    /** May this player build here? Unclaimed land is open. */
    public boolean canBuild(UUID player, Location l) {
        Claim c = at(l);
        return c == null || c.owner().equals(player) || c.trusted().contains(player);
    }

    public void save(YamlConfiguration y) {
        y.set("claims", null);
        for (Map.Entry<String, Claim> e : claims.entrySet()) {
            String path = "claims." + e.getKey().replace('.', '_');
            y.set(path + ".key", e.getKey());
            y.set(path + ".owner", e.getValue().owner().toString());
            List<String> t = new ArrayList<>();
            for (UUID u : e.getValue().trusted()) t.add(u.toString());
            y.set(path + ".trusted", t);
        }
    }

    public void load(YamlConfiguration y) {
        claims.clear();
        ConfigurationSection s = y.getConfigurationSection("claims");
        if (s == null) return;
        for (String k : s.getKeys(false)) {
            ConfigurationSection c = s.getConfigurationSection(k);
            if (c == null) continue;
            try {
                Set<UUID> trusted = new HashSet<>();
                for (String t : c.getStringList("trusted")) trusted.add(UUID.fromString(t));
                claims.put(c.getString("key", k), new Claim(UUID.fromString(c.getString("owner", "")), trusted));
            } catch (IllegalArgumentException bad) { /* skip a corrupt entry */ }
        }
    }

    public int size() { return claims.size(); }
}
