package __PKG__;

import org.bukkit.entity.AnimalTamer;
import org.bukkit.entity.AreaEffectCloud;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.entity.Projectile;
import org.bukkit.entity.Tameable;
import org.bukkit.entity.TNTPrimed;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.projectiles.ProjectileSource;

/**
 * "Which player is responsible?" for a hit or a kill. The damager is often NOT the player:
 * arrows, tridents, snowballs (Projectile -> shooter), primed TNT (source), lingering potions
 * (AreaEffectCloud -> source) and tamed wolves (owner). Use it for kill streaks, PvP rules,
 * bounties, claim protection and combat tags.
 */
public final class Attribution {

    private Attribution() {}

    public static Player responsiblePlayer(Entity damager) {
        if (damager == null) return null;
        if (damager instanceof Player p) return p;
        if (damager instanceof Projectile proj) return fromSource(proj.getShooter());
        if (damager instanceof TNTPrimed tnt) return responsiblePlayer(tnt.getSource());
        if (damager instanceof AreaEffectCloud cloud) return fromSource(cloud.getSource());
        if (damager instanceof Tameable pet && pet.isTamed()) {
            AnimalTamer owner = pet.getOwner();
            if (owner instanceof Player p) return p;
        }
        return null;
    }

    /** For EntityDamageEvent listeners: the responsible player, or null for falls, lava, mobs... */
    public static Player responsiblePlayer(EntityDamageEvent e) {
        return e instanceof EntityDamageByEntityEvent by ? responsiblePlayer(by.getDamager()) : null;
    }

    /** The killer the server credits, falling back to the last damage cause (covers arrows/TNT). */
    public static Player killer(LivingEntity victim) {
        Player k = victim.getKiller();
        if (k != null) return k;
        return responsiblePlayer(victim.getLastDamageCause());
    }

    private static Player fromSource(ProjectileSource src) {
        if (src instanceof Player p) return p;
        if (src instanceof Entity e && !(src instanceof Player)) return responsiblePlayer(e);
        return null;
    }
}
