cat > cuboid-region/Cuboid.java <<'EOF'
package __PKG__;

import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.configuration.ConfigurationSection;

import java.util.UUID;

/**
 * An axis-aligned box of whole blocks in one world (arenas, hills, safe zones, regions).
 * Built from two corners in any order; contains() is inclusive on both corners. Stored by world
 * NAME + ints, so it loads even when the world is not loaded yet (resolve the World lazily).
 */
public record Cuboid(String world, int minX, int minY, int minZ, int maxX, int maxY, int maxZ) {

    public static Cuboid of(Location a, Location b) {
        if (a.getWorld() == null || b.getWorld() == null || !a.getWorld().equals(b.getWorld()))
            throw new IllegalArgumentException("Both corners must be in the same world");
        return new Cuboid(a.getWorld().getName(),
                Math.min(a.getBlockX(), b.getBlockX()), Math.min(a.getBlockY(), b.getBlockY()), Math.min(a.getBlockZ(), b.getBlockZ()),
                Math.max(a.getBlockX(), b.getBlockX()), Math.max(a.getBlockY(), b.getBlockY()), Math.max(a.getBlockZ(), b.getBlockZ()));
    }

    public boolean contains(Location l) {
        if (l == null || l.getWorld() == null || !l.getWorld().getName().equals(world)) return false;
        int x = l.getBlockX(), y = l.getBlockY(), z = l.getBlockZ();
        return x >= minX && x <= maxX && y >= minY && y <= maxY && z >= minZ && z <= maxZ;
    }

    public boolean contains(Block b) { return contains(b.getLocation()); }

    /** Ignores height: for "standing on the hill" checks where jumping should not count as leaving. */
    public boolean containsColumn(Location l) {
        if (l == null || l.getWorld() == null || !l.getWorld().getName().equals(world)) return false;
        int x = l.getBlockX(), z = l.getBlockZ();
        return x >= minX && x <= maxX && z >= minZ && z <= maxZ;
    }

    public long volume() { return (long) (maxX - minX + 1) * (maxY - minY + 1) * (maxZ - minZ + 1); }

    public World bukkitWorld() { return Bukkit.getWorld(world); }

    public Location center() {
        World w = bukkitWorld();
        return w == null ? null : new Location(w, (minX + maxX + 1) / 2.0, minY, (minZ + maxZ + 1) / 2.0);
    }

    public void save(ConfigurationSection s) {
        s.set("world", world);
        s.set("min", minX + "," + minY + "," + minZ);
        s.set("max", maxX + "," + maxY + "," + maxZ);
    }

    /** null when the section is missing or malformed. */
    public static Cuboid load(ConfigurationSection s) {
        if (s == null) return null;
        String w = s.getString("world");
        int[] a = ints(s.getString("min")), b = ints(s.getString("max"));
        if (w == null || a == null || b == null) return null;
        return new Cuboid(w, Math.min(a[0], b[0]), Math.min(a[1], b[1]), Math.min(a[2], b[2]), Math.max(a[0], b[0]), Math.max(a[1], b[1]), Math.max(a[2], b[2]));
    }

    private static int[] ints(String s) {
        if (s == null) return null;
        String[] p = s.split(",");
        if (p.length != 3) return null;
        try { return new int[]{Integer.parseInt(p[0].trim()), Integer.parseInt(p[1].trim()), Integer.parseInt(p[2].trim())}; }
        catch (NumberFormatException e) { return null; }
    }

    /** Unused helper kept tiny: a stable id for maps. */
    public UUID id() { return UUID.nameUUIDFromBytes(toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)); }
}
