package __PKG__;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.block.Block;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockExplodeEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.entity.EntityExplodeEvent;
import org.bukkit.event.player.PlayerBucketEmptyEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.InventoryHolder;

/**
 * Enforces ClaimStore: blocks break/place/bucket/container use by strangers, and stops
 * explosions (TNT, creepers, beds) from destroying claimed blocks. Players with the bypass
 * permission are never blocked.
 */
public class ClaimProtection implements Listener {

    private final ClaimStore store;
    private final String bypass;

    public ClaimProtection(ClaimStore store, String bypassPermission) {
        this.store = store;
        this.bypass = bypassPermission;
    }

    private boolean denied(Player p, Block b) {
        if (bypass != null && p.hasPermission(bypass)) return false;
        if (store.canBuild(p.getUniqueId(), b.getLocation())) return false;
        p.sendActionBar(Component.text("This land is claimed.", NamedTextColor.RED));
        return true;
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) { if (denied(e.getPlayer(), e.getBlock())) e.setCancelled(true); }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onPlace(BlockPlaceEvent e) { if (denied(e.getPlayer(), e.getBlock())) e.setCancelled(true); }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBucket(PlayerBucketEmptyEvent e) { if (denied(e.getPlayer(), e.getBlock())) e.setCancelled(true); }

    @EventHandler(priority = EventPriority.HIGH)
    public void onInteract(PlayerInteractEvent e) {
        Block b = e.getClickedBlock();
        if (b == null || !(b.getState() instanceof InventoryHolder)) return;
        if (denied(e.getPlayer(), b)) e.setCancelled(true);
    }

    @EventHandler(ignoreCancelled = true)
    public void onEntityExplode(EntityExplodeEvent e) { e.blockList().removeIf(b -> store.at(b.getLocation()) != null); }

    @EventHandler(ignoreCancelled = true)
    public void onBlockExplode(BlockExplodeEvent e) { e.blockList().removeIf(b -> store.at(b.getLocation()) != null); }
}
