package __PKG__;

import io.papermc.paper.event.player.AsyncChatEvent;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BiConsumer;

/**
 * AFK detection: last activity per player (block-changing moves, chat, interaction), a 1-second
 * check marks players AFK after the timeout and calls back on every change (show "[AFK]" in tab,
 * announce...). Head turning alone does not count as activity (anti-AFK pools look around).
 * Chat runs async, so activity is stored in a ConcurrentHashMap and state changes happen in the
 * main-thread timer.
 */
public class AfkTracker implements Listener {

    private final JavaPlugin plugin;
    private final Map<UUID, Long> lastActive = new ConcurrentHashMap<>();
    private final Set<UUID> afk = ConcurrentHashMap.newKeySet();
    private final BiConsumer<Player, Boolean> onChange;
    private volatile long timeoutMs;
    private BukkitTask task;

    public AfkTracker(JavaPlugin plugin, long timeoutMs, BiConsumer<Player, Boolean> onChange) {
        this.plugin = plugin;
        this.timeoutMs = timeoutMs;
        this.onChange = onChange;
    }

    public void start() {
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
        task = Bukkit.getScheduler().runTaskTimer(plugin, this::check, 20L, 20L);
    }

    public void stop() { if (task != null) task.cancel(); task = null; }

    public void setTimeout(long ms) { this.timeoutMs = ms; }

    public boolean isAfk(UUID id) { return afk.contains(id); }

    /** Manual /afk toggle. */
    public void setAfk(Player p, boolean value) {
        if (value) { if (afk.add(p.getUniqueId())) onChange.accept(p, true); }
        else { lastActive.put(p.getUniqueId(), System.currentTimeMillis()); if (afk.remove(p.getUniqueId())) onChange.accept(p, false); }
    }

    public void touch(UUID id) { lastActive.put(id, System.currentTimeMillis()); }

    /** Main thread. Exposed for tests: decides AFK from timestamps. */
    public void check() {
        long now = System.currentTimeMillis();
        for (Player p : Bukkit.getOnlinePlayers()) {
            UUID id = p.getUniqueId();
            long last = lastActive.computeIfAbsent(id, k -> now);
            boolean shouldBeAfk = now - last >= timeoutMs;
            if (shouldBeAfk && afk.add(id)) onChange.accept(p, true);
            else if (!shouldBeAfk && afk.remove(id)) onChange.accept(p, false);
        }
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) { if (e.hasChangedBlock()) touch(e.getPlayer().getUniqueId()); }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onChat(AsyncChatEvent e) { touch(e.getPlayer().getUniqueId()); }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onInteract(PlayerInteractEvent e) { touch(e.getPlayer().getUniqueId()); }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) { lastActive.remove(e.getPlayer().getUniqueId()); afk.remove(e.getPlayer().getUniqueId()); }
}
