package __PKG__;

import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Balances in whole minor units (long "cents"), never double (0.1 + 0.2 != 0.3), with overflow
 * checks and no negative balances. Every change goes through one synchronized method, so /pay
 * from two places at once cannot duplicate money. Persist with save()/load() on change + on a
 * timer + in onDisable.
 * Display: Ledger.format(12345, 2) -> "123.45".
 */
public class Ledger {

    public enum Result { OK, INSUFFICIENT_FUNDS, INVALID_AMOUNT, SAME_ACCOUNT, OVERFLOW }

    private final Map<UUID, Long> balances = new ConcurrentHashMap<>();
    private final long startingBalance;
    private volatile boolean dirty;

    public Ledger(long startingBalance) { this.startingBalance = Math.max(0, startingBalance); }

    public long balance(UUID id) { return balances.getOrDefault(id, startingBalance); }

    public boolean isDirty() { return dirty; }

    public synchronized Result deposit(UUID id, long amount) {
        if (amount <= 0) return Result.INVALID_AMOUNT;
        try { balances.put(id, Math.addExact(balance(id), amount)); } catch (ArithmeticException e) { return Result.OVERFLOW; }
        dirty = true;
        return Result.OK;
    }

    public synchronized Result withdraw(UUID id, long amount) {
        if (amount <= 0) return Result.INVALID_AMOUNT;
        long b = balance(id);
        if (b < amount) return Result.INSUFFICIENT_FUNDS;
        balances.put(id, b - amount);
        dirty = true;
        return Result.OK;
    }

    /** Admin set (>= 0). */
    public synchronized Result set(UUID id, long amount) {
        if (amount < 0) return Result.INVALID_AMOUNT;
        balances.put(id, amount);
        dirty = true;
        return Result.OK;
    }

    /** Atomic transfer: both sides change or neither does. */
    public synchronized Result transfer(UUID from, UUID to, long amount) {
        if (from.equals(to)) return Result.SAME_ACCOUNT;
        if (amount <= 0) return Result.INVALID_AMOUNT;
        long a = balance(from), b = balance(to);
        if (a < amount) return Result.INSUFFICIENT_FUNDS;
        long nb;
        try { nb = Math.addExact(b, amount); } catch (ArithmeticException e) { return Result.OVERFLOW; }
        balances.put(from, a - amount);
        balances.put(to, nb);
        dirty = true;
        return Result.OK;
    }

    /** Highest balances first. */
    public List<Map.Entry<UUID, Long>> top(int n) {
        List<Map.Entry<UUID, Long>> all = new ArrayList<>(balances.entrySet());
        all.sort((x, y) -> Long.compare(y.getValue(), x.getValue()));
        return all.subList(0, Math.min(n, all.size()));
    }

    /** Parses "12.5" with 2 decimals -> 1250; null for junk, negatives or too many decimals. */
    public static Long parse(String text, int decimals) {
        if (text == null || !text.matches("\\d{1,15}(\\.\\d+)?")) return null;
        String[] p = text.split("\\.");
        String frac = p.length > 1 ? p[1] : "";
        if (frac.length() > decimals) return null;
        StringBuilder f = new StringBuilder(frac);
        while (f.length() < decimals) f.append('0');
        try { return Long.parseLong(p[0] + f); } catch (NumberFormatException e) { return null; }
    }

    public static String format(long minor, int decimals) {
        if (decimals <= 0) return Long.toString(minor);
        long pow = (long) Math.pow(10, decimals);
        return (minor / pow) + "." + String.format("%0" + decimals + "d", Math.abs(minor % pow));
    }

    public synchronized void save(YamlConfiguration y) {
        y.set("balances", null);
        balances.forEach((id, v) -> y.set("balances." + id, v));
        dirty = false;
    }

    public synchronized void load(YamlConfiguration y) {
        balances.clear();
        ConfigurationSection s = y.getConfigurationSection("balances");
        if (s == null) return;
        for (String k : s.getKeys(false)) {
            try { balances.put(UUID.fromString(k), Math.max(0, s.getLong(k))); } catch (IllegalArgumentException bad) { /* skip */ }
        }
        dirty = false;
    }
}
