package __PKG__;

import io.papermc.paper.event.player.AsyncChatEvent;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.TextReplacementConfig;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;

import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Word filter + timed mutes on Paper's AsyncChatEvent. That event runs OFF the main thread:
 * this class only touches thread-safe state (ConcurrentHashMap, a volatile compiled pattern) and
 * never calls world/player-changing API from the handler. For punishments that need the main
 * thread, schedule them: Bukkit.getScheduler().runTask(plugin, () -> ...).
 * Filtering edits the message Component (TextReplacementConfig), so formatting is kept.
 */
public class ChatGuard implements Listener {

    private volatile Pattern bad = null;
    private final Map<UUID, Long> mutedUntil = new ConcurrentHashMap<>();
    private final String bypassPermission;

    public ChatGuard(String bypassPermission) { this.bypassPermission = bypassPermission; }

    /** Whole words, case-insensitive. Call again on /reload. */
    public void setWords(List<String> words) {
        List<String> clean = words.stream().map(String::trim).filter(w -> !w.isEmpty()).map(Pattern::quote).collect(Collectors.toList());
        bad = clean.isEmpty() ? null : Pattern.compile("(?iu)\\b(" + String.join("|", clean) + ")\\b");
    }

    public void mute(UUID id, long minutes) { mutedUntil.put(id, System.currentTimeMillis() + minutes * 60_000L); }

    public boolean unmute(UUID id) { return mutedUntil.remove(id) != null; }

    public long mutedMillisLeft(UUID id) {
        Long until = mutedUntil.get(id);
        if (until == null) return 0;
        long left = until - System.currentTimeMillis();
        if (left <= 0) { mutedUntil.remove(id); return 0; }
        return left;
    }

    public Map<UUID, Long> mutes() { return mutedUntil; }

    /** Replaces bad words with *** (also usable for signs, books, names). */
    public Component filter(Component message) {
        Pattern p = bad;
        if (p == null) return message;
        return message.replaceText(TextReplacementConfig.builder().match(p).replacement("***").build());
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onChat(AsyncChatEvent e) {
        UUID id = e.getPlayer().getUniqueId();
        long left = mutedMillisLeft(id);
        if (left > 0) {
            e.setCancelled(true);
            e.getPlayer().sendMessage(Component.text("You are muted for " + ((left + 59_999) / 60_000) + " more minute(s).", NamedTextColor.RED));
            return;
        }
        if (bypassPermission != null && e.getPlayer().hasPermission(bypassPermission)) return;
        e.message(filter(e.message()));
    }
}
