package __PKG__;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.minimessage.MiniMessage;
import net.kyori.adventure.text.minimessage.tag.resolver.Placeholder;
import net.kyori.adventure.title.Title;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;

import java.time.Duration;

/**
 * Custom join/quit messages and a first-join welcome title, from config.yml:
 *   join: "<green>+ <player>"   quit: "<red>- <player>"   (empty string = no message)
 *   first-join-title: "<gold>Welcome!"   first-join-subtitle: "<gray>Enjoy, <player>"
 * Uses event.joinMessage(Component) (the String setters are deprecated) and hasPlayedBefore().
 */
public class JoinMessages implements Listener {

    private static final MiniMessage MM = MiniMessage.miniMessage();
    private volatile ConfigurationSection cfg;

    public JoinMessages(ConfigurationSection cfg) { this.cfg = cfg; }

    public void reload(ConfigurationSection cfg) { this.cfg = cfg; }

    Component render(String path, String player) {
        String raw = cfg == null ? null : cfg.getString(path);
        if (raw == null) return null;
        if (raw.isEmpty()) return Component.empty();
        return MM.deserialize(raw, Placeholder.unparsed("player", player));
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        String name = e.getPlayer().getName();
        Component msg = render("join", name);
        if (msg != null) e.joinMessage(msg.equals(Component.empty()) ? null : msg);
        if (!e.getPlayer().hasPlayedBefore()) {
            Component t = render("first-join-title", name);
            Component s = render("first-join-subtitle", name);
            if (t != null || s != null) {
                e.getPlayer().showTitle(Title.title(t == null ? Component.empty() : t, s == null ? Component.empty() : s,
                        Title.Times.times(Duration.ofMillis(500), Duration.ofSeconds(4), Duration.ofMillis(800))));
            }
        }
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) {
        Component msg = render("quit", e.getPlayer().getName());
        if (msg != null) e.quitMessage(msg.equals(Component.empty()) ? null : msg);
    }
}
