package __PKG__;

import org.bukkit.Color;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.Particle;
import org.bukkit.World;
import org.bukkit.block.data.BlockData;
import org.bukkit.inventory.ItemStack;

import java.util.Locale;

/**
 * Particles from config names with the data they REQUIRE filled in automatically (DUST needs
 * DustOptions, BLOCK needs BlockData, ITEM needs an ItemStack, ENTITY_EFFECT a Color...).
 * Spawning a data particle without data throws at runtime; this never does. Old names
 * (REDSTONE, SPELL_WITCH, VILLAGER_HAPPY) are rejected by Particle.valueOf, so parse() returns null.
 * Shapes: circle, helix, line - cheap enough to call every few ticks.
 */
public final class Particles {

    private Particles() {}

    /** Parses "flame", "DUST", "heart"... null when unknown on this server version. */
    public static Particle parse(String name) {
        if (name == null) return null;
        try { return Particle.valueOf(name.trim().toUpperCase(Locale.ROOT)); } catch (IllegalArgumentException e) { return null; }
    }

    /** A sensible default data object for particles that need one (null when none is needed). */
    public static Object defaultData(Particle p, Color color) {
        Class<?> t = p.getDataType();
        if (t == Void.class) return null;
        Color c = color == null ? Color.RED : color;
        if (t == Particle.DustOptions.class) return new Particle.DustOptions(c, 1.0f);
        if (t == Particle.DustTransition.class) return new Particle.DustTransition(c, Color.WHITE, 1.0f);
        if (t == Color.class) return c;
        if (t == BlockData.class) return Material.STONE.createBlockData();
        if (t == ItemStack.class) return new ItemStack(Material.STONE);
        if (t == Float.class) return 0f;
        if (t == Integer.class) return 0;
        return UNSUPPORTED;
    }

    private static final Object UNSUPPORTED = new Object();

    /** True when spawn() can safely show this particle. */
    public static boolean spawnable(Particle p) { return defaultData(p, null) != UNSUPPORTED; }

    public static void spawn(World w, Particle p, Location at, int count, double spread, Color color) {
        Object data = defaultData(p, color);
        if (data == UNSUPPORTED) return;
        if (data == null) w.spawnParticle(p, at, count, spread, spread, spread, 0);
        else w.spawnParticle(p, at, count, spread, spread, spread, 0, data);
    }

    public static void circle(Location center, double radius, int points, Particle p, Color color) {
        World w = center.getWorld();
        if (w == null) return;
        for (int i = 0; i < points; i++) {
            double a = 2 * Math.PI * i / points;
            spawn(w, p, center.clone().add(Math.cos(a) * radius, 0, Math.sin(a) * radius), 1, 0, color);
        }
    }

    public static void helix(Location base, double radius, double height, int points, Particle p, Color color) {
        World w = base.getWorld();
        if (w == null) return;
        for (int i = 0; i < points; i++) {
            double f = i / (double) points, a = f * 4 * Math.PI;
            spawn(w, p, base.clone().add(Math.cos(a) * radius, f * height, Math.sin(a) * radius), 1, 0, color);
        }
    }

    public static void line(Location from, Location to, double step, Particle p, Color color) {
        World w = from.getWorld();
        if (w == null || to.getWorld() != w) return;
        double len = from.distance(to);
        if (len == 0) return;
        org.bukkit.util.Vector dir = to.toVector().subtract(from.toVector()).normalize().multiply(step);
        Location cur = from.clone();
        for (double d = 0; d <= len; d += step) { spawn(w, p, cur, 1, 0, color); cur.add(dir); }
    }
}
