package __PKG__;

import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.World;
import org.bukkit.configuration.ConfigurationSection;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Named locations (homes, warps, spawn, arenas) stored as world NAME + coordinates, resolved to
 * a Location only when used. Storing Location objects directly fails to load when that world is
 * not loaded yet (or was deleted), which silently wipes the data on the next save; this keeps
 * the entry and reports it as unavailable instead.
 * Names are case-insensitive, letters/digits/_/- only, with an optional maximum count.
 */
public class LocationBook {

    public record Spot(String world, double x, double y, double z, float yaw, float pitch) {
        public static Spot of(Location l) { return new Spot(l.getWorld().getName(), l.getX(), l.getY(), l.getZ(), l.getYaw(), l.getPitch()); }
        /** null when the world is not loaded / no longer exists. */
        public Location toLocation() {
            World w = Bukkit.getWorld(world);
            return w == null ? null : new Location(w, x, y, z, yaw, pitch);
        }
    }

    public enum Result { OK, LIMIT_REACHED, BAD_NAME }

    private final Map<String, Spot> spots = new LinkedHashMap<>();

    public static boolean validName(String name) { return name != null && name.matches("[A-Za-z0-9_-]{1,32}"); }

    public Result set(String name, Location l, int max) {
        if (!validName(name) || l.getWorld() == null) return Result.BAD_NAME;
        String k = name.toLowerCase(Locale.ROOT);
        if (!spots.containsKey(k) && max > 0 && spots.size() >= max) return Result.LIMIT_REACHED;
        spots.put(k, Spot.of(l));
        return Result.OK;
    }

    public Spot get(String name) { return name == null ? null : spots.get(name.toLowerCase(Locale.ROOT)); }

    public boolean remove(String name) { return name != null && spots.remove(name.toLowerCase(Locale.ROOT)) != null; }

    public List<String> names() { List<String> n = new ArrayList<>(spots.keySet()); Collections.sort(n); return n; }

    public int size() { return spots.size(); }

    public void save(ConfigurationSection s) {
        for (String k : new ArrayList<>(s.getKeys(false))) s.set(k, null);
        spots.forEach((k, v) -> {
            ConfigurationSection c = s.createSection(k);
            c.set("world", v.world()); c.set("x", v.x()); c.set("y", v.y()); c.set("z", v.z());
            c.set("yaw", (double) v.yaw()); c.set("pitch", (double) v.pitch());
        });
    }

    public void load(ConfigurationSection s) {
        spots.clear();
        if (s == null) return;
        for (String k : s.getKeys(false)) {
            ConfigurationSection c = s.getConfigurationSection(k);
            if (c == null || c.getString("world") == null) continue;
            spots.put(k.toLowerCase(Locale.ROOT), new Spot(c.getString("world"), c.getDouble("x"), c.getDouble("y"), c.getDouble("z"),
                    (float) c.getDouble("yaw"), (float) c.getDouble("pitch")));
        }
    }
}
