package __PKG__;

import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.UUID;
import java.util.function.Consumer;

/**
 * Minigame round lifecycle as an explicit state machine:
 * WAITING -(min players)-> COUNTDOWN -(timer)-> RUNNING -(end())-> ENDING -(delay)-> WAITING.
 * Players are tracked by UUID; leave() is the ONE place a player is cleaned up (call it from
 * quit, kick, death-elimination and end), so nobody is left with arena items/effects.
 * Hooks are plain callbacks: onStart, onEnd (winner may be null), onLeave(player) for cleanup.
 * Wire: listener for PlayerQuitEvent -> arena.leave(player). onDisable -> arena.shutdown().
 */
public class Arena {

    public enum State { WAITING, COUNTDOWN, RUNNING, ENDING }

    private final JavaPlugin plugin;
    private final String name;
    private final int minPlayers, maxPlayers, countdownSeconds;
    private final Set<UUID> players = new LinkedHashSet<>();
    private State state = State.WAITING;
    private BukkitTask timer;
    private int countdownLeft;

    public Consumer<Arena> onStart = a -> {};
    public Consumer<UUID> onEnd = winner -> {};
    public Consumer<Player> onLeave = p -> {};
    public Consumer<Integer> onCountdown = s -> {};

    public Arena(JavaPlugin plugin, String name, int minPlayers, int maxPlayers, int countdownSeconds) {
        this.plugin = plugin;
        this.name = name;
        this.minPlayers = Math.max(1, minPlayers);
        this.maxPlayers = Math.max(this.minPlayers, maxPlayers);
        this.countdownSeconds = Math.max(0, countdownSeconds);
    }

    public String name() { return name; }
    public State state() { return state; }
    public Set<UUID> players() { return Collections.unmodifiableSet(players); }
    public boolean contains(UUID id) { return players.contains(id); }

    /** False when running/full/already in. */
    public boolean join(UUID id) {
        if (state == State.RUNNING || state == State.ENDING || players.size() >= maxPlayers || !players.add(id)) return false;
        if (state == State.WAITING && players.size() >= minPlayers) startCountdown();
        return true;
    }

    public void leave(UUID id) {
        if (!players.remove(id)) return;
        Player p = Bukkit.getPlayer(id);
        if (p != null) onLeave.accept(p);
        if (state == State.COUNTDOWN && players.size() < minPlayers) { cancelTimer(); state = State.WAITING; }
        else if (state == State.RUNNING && players.size() <= 1) end(players.isEmpty() ? null : players.iterator().next());
    }

    public void forceStart() { if (state == State.WAITING || state == State.COUNTDOWN) { cancelTimer(); begin(); } }

    private void startCountdown() {
        state = State.COUNTDOWN;
        countdownLeft = countdownSeconds;
        if (countdownSeconds == 0) { begin(); return; }
        timer = Bukkit.getScheduler().runTaskTimer(plugin, () -> {
            if (countdownLeft <= 0) { cancelTimer(); begin(); return; }
            onCountdown.accept(countdownLeft--);
        }, 0L, 20L);
    }

    private void begin() { state = State.RUNNING; onStart.accept(this); }

    /** Ends the round; winner may be null. Everyone left is cleaned up after 5 seconds. */
    public void end(UUID winner) {
        if (state == State.ENDING || state == State.WAITING) return;
        cancelTimer();
        state = State.ENDING;
        onEnd.accept(winner);
        timer = Bukkit.getScheduler().runTaskLater(plugin, this::reset, 100L);
    }

    private void reset() {
        timer = null;
        for (UUID id : Set.copyOf(players)) { Player p = Bukkit.getPlayer(id); if (p != null) onLeave.accept(p); }
        players.clear();
        state = State.WAITING;
    }

    /** onDisable: synchronous cleanup, no new tasks. */
    public void shutdown() { cancelTimer(); reset(); }

    private void cancelTimer() { if (timer != null) { timer.cancel(); timer = null; } }
}
