import java.util.Map;
import java.util.UUID;
import java.util.function.BiConsumer;

/**
 * Quest/challenge progress from gameplay: KILL <entity type>, MINE <material>, WALK <blocks>.
 * Objectives are data (from config), progress is per player + objective id, completion fires
 * once. Walking counts whole blocks moved (hasChangedBlock), not raw move events, so it is cheap.
 * Wire: tracker = new ObjectiveTracker((player, obj) -> reward); registerEvents(tracker, plugin);
 *       tracker.assign(uuid, List.of(new Objective("zombies", Kind.KILL, "ZOMBIE", 10), ...));
 */
public class ObjectiveTracker implements Listener {

    public enum Kind { KILL, MINE, WALK }

    /** target: an EntityType name for KILL, a Material name for MINE, ignored for WALK ("*" = any). */
    public record Objective(String id, Kind kind, String target, int amount) {}

    private final Map<UUID, List<Objective>> assigned = new HashMap<>();
    private final Map<UUID, Map<String, Integer>> progress = new HashMap<>();
    private final BiConsumer<Player, Objective> onComplete;

    public ObjectiveTracker(BiConsumer<Player, Objective> onComplete) { this.onComplete = onComplete; }

    public void assign(UUID player, List<Objective> objectives) {
        assigned.put(player, new ArrayList<>(objectives));
        progress.put(player, new HashMap<>());
    }

    public int progress(UUID player, String objectiveId) {
        return progress.getOrDefault(player, Map.of()).getOrDefault(objectiveId, 0);
    }

    public boolean done(UUID player, Objective o) { return progress(player, o.id()) >= o.amount(); }

    public List<Objective> objectives(UUID player) { return assigned.getOrDefault(player, List.of()); }

    public Map<String, Integer> snapshot(UUID player) { return Map.copyOf(progress.getOrDefault(player, Map.of())); }

    public void restore(UUID player, Map<String, Integer> values) { progress.computeIfAbsent(player, k -> new HashMap<>()).putAll(values); }

    /** Adds `n` to every matching objective of the player (also callable from your own events). */
    public void record(Player p, Kind kind, String target, int n) {
        List<Objective> list = assigned.get(p.getUniqueId());
        if (list == null) return;
        Map<String, Integer> prog = progress.get(p.getUniqueId());
        for (Objective o : list) {
            if (o.kind() != kind) continue;
            if (kind != Kind.WALK && !o.target().equals("*") && !o.target().equalsIgnoreCase(target)) continue;
            int before = prog.getOrDefault(o.id(), 0);
            if (before >= o.amount()) continue;
            int after = Math.min(o.amount(), before + n);
            prog.put(o.id(), after);
            if (after >= o.amount()) onComplete.accept(p, o);
        }
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onKill(EntityDeathEvent e) {
        Player k = e.getEntity().getKiller();
        if (k != null) record(k, Kind.KILL, e.getEntityType().name(), 1);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onMine(BlockBreakEvent e) { record(e.getPlayer(), Kind.MINE, e.getBlock().getType().name(), 1); }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onWalk(PlayerMoveEvent e) { if (e.hasChangedBlock()) record(e.getPlayer(), Kind.WALK, "*", 1); }

    /** Validates config targets against this server version (null = fine, else the problem). */
    public static String validate(Objective o) {
        if (o.amount() <= 0) return o.id() + ": amount must be positive";
        if (o.target().equals("*") || o.kind() == Kind.WALK) return null;
        try {
            if (o.kind() == Kind.KILL) EntityType.valueOf(o.target().toUpperCase());
            else if (Material.matchMaterial(o.target()) == null) return o.id() + ": unknown block " + o.target();
        } catch (IllegalArgumentException e) { return o.id() + ": unknown mob " + o.target(); }
        return null;
    }
}
