package __PKG__;

import org.bukkit.configuration.ConfigurationSection;

import java.time.Clock;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.temporal.ChronoUnit;
import java.util.UUID;

/**
 * Daily rewards / daily quests bookkeeping: "has this player claimed today?", login streaks that
 * grow on consecutive days and reset after a missed day. Days are calendar days in ONE zone
 * (the server's, or one from config), stored as ISO dates, so restarts and time changes are safe.
 * Storage is any ConfigurationSection (e.g. the player's file from player-data-store).
 */
public class DailyStreak {

    public record Claim(boolean allowed, int streak, boolean reset) {}

    private final Clock clock;

    public DailyStreak(ZoneId zone) { this.clock = Clock.system(zone); }

    /** For tests: a fixed or offset clock. */
    public DailyStreak(Clock clock) { this.clock = clock; }

    public LocalDate today() { return LocalDate.now(clock); }

    /**
     * Claims today's reward for the data in `s` ("last-claim", "streak"). Returns allowed=false when
     * already claimed today. Writes the new values into the section; save it afterwards.
     */
    public Claim claim(ConfigurationSection s) {
        LocalDate today = today();
        String raw = s.getString("last-claim");
        LocalDate last = null;
        try { if (raw != null) last = LocalDate.parse(raw); } catch (RuntimeException ignored) { /* corrupt -> treat as never */ }
        int streak = s.getInt("streak", 0);
        if (last != null && !last.isBefore(today)) return new Claim(false, streak, false);
        boolean consecutive = last != null && ChronoUnit.DAYS.between(last, today) == 1;
        boolean reset = last != null && !consecutive;
        streak = consecutive ? streak + 1 : 1;
        s.set("last-claim", today.toString());
        s.set("streak", streak);
        return new Claim(true, streak, reset);
    }

    public boolean claimedToday(ConfigurationSection s) {
        String raw = s.getString("last-claim");
        return raw != null && raw.equals(today().toString());
    }

    /** Daily seed for "3 random quests per day" that is the same all day and differs per player. */
    public long dailySeed(UUID player) { return today().toEpochDay() * 31L + player.hashCode(); }
}
