package __PKG__;

import org.bukkit.Bukkit;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Spreads big main-thread jobs (resetting an arena of 50k blocks, scanning chunks, giving items to
 * everyone) over many ticks with a time budget per tick, so the server never freezes. Work stays
 * on the main thread (Bukkit API is not thread-safe); only the AMOUNT per tick is limited.
 * Wire: TickBudget b = new TickBudget(plugin, 5); b.add(() -> block.setType(...)); ... b.start(() -> done());
 */
public class TickBudget {

    private final JavaPlugin plugin;
    private final long budgetNanos;
    private final Deque<Runnable> queue = new ArrayDeque<>();
    private BukkitTask task;
    private Runnable onDone;
    private int done;

    /** millisPerTick: 2-10 is sensible (a tick is 50 ms in total). */
    public TickBudget(JavaPlugin plugin, int millisPerTick) {
        this.plugin = plugin;
        this.budgetNanos = Math.max(1, millisPerTick) * 1_000_000L;
    }

    public TickBudget add(Runnable job) { queue.add(job); return this; }

    public int pending() { return queue.size(); }

    public int completed() { return done; }

    public boolean isRunning() { return task != null; }

    public void start(Runnable onDone) {
        this.onDone = onDone;
        if (task != null) return;
        task = Bukkit.getScheduler().runTaskTimer(plugin, this::tick, 1L, 1L);
    }

    private void tick() {
        long end = System.nanoTime() + budgetNanos;
        do {
            Runnable r = queue.poll();
            if (r == null) break;
            try { r.run(); } catch (Throwable t) { plugin.getLogger().warning("Batched job failed: " + t); }
            done++;
        } while (System.nanoTime() < end);
        if (queue.isEmpty()) {
            cancel();
            if (onDone != null) onDone.run();
        }
    }

    /** Stops; remaining jobs stay queued (runAllNow() to finish them synchronously, e.g. onDisable). */
    public void cancel() { if (task != null) { task.cancel(); task = null; } }

    public void runAllNow() {
        cancel();
        Runnable r;
        while ((r = queue.poll()) != null) { try { r.run(); } catch (Throwable t) { plugin.getLogger().warning("Batched job failed: " + t); } done++; }
    }
}
