package __PKG__;

import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.block.data.BlockData;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Temporary block changes that put themselves back: regenerating ores, spleef floors, explosion
 * craters, temporary bridges/walls. Remembers the ORIGINAL BlockData the first time a block is
 * changed (so overlapping changes restore the real original), restores after a delay, and
 * restoreAll() puts everything back synchronously in onDisable so a restart never leaves holes.
 */
public class BlockRestorer {

    private final JavaPlugin plugin;
    private final Map<Location, BlockData> originals = new LinkedHashMap<>();
    private final Map<Location, BukkitTask> timers = new LinkedHashMap<>();

    public BlockRestorer(JavaPlugin plugin) { this.plugin = plugin; }

    /** Sets the block to `temporary` now and back to its original after `ticks` (0 = only on restoreAll). */
    public void setTemporarily(Block block, Material temporary, long ticks) { setTemporarily(block, temporary.createBlockData(), ticks); }

    public void setTemporarily(Block block, BlockData temporary, long ticks) {
        Location key = block.getLocation();
        originals.putIfAbsent(key, block.getBlockData().clone());
        block.setBlockData(temporary, false);
        schedule(key, ticks);
    }

    /** Call when a player breaks a block you want to regrow (e.g. in BlockBreakEvent, before it breaks). */
    public void remember(Block block, long ticks) {
        Location key = block.getLocation();
        originals.putIfAbsent(key, block.getBlockData().clone());
        schedule(key, ticks);
    }

    private void schedule(Location key, long ticks) {
        BukkitTask old = timers.remove(key);
        if (old != null) old.cancel();
        if (ticks > 0) timers.put(key, Bukkit.getScheduler().runTaskLater(plugin, () -> restore(key), ticks));
    }

    public boolean isTracked(Block b) { return originals.containsKey(b.getLocation()); }

    public int tracked() { return originals.size(); }

    public void restore(Location key) {
        BukkitTask t = timers.remove(key);
        if (t != null) t.cancel();
        BlockData data = originals.remove(key);
        if (data != null && key.getWorld() != null) key.getBlock().setBlockData(data, false);
    }

    /** Synchronous, for onDisable and "/arena reset". */
    public void restoreAll() {
        for (Location k : new java.util.ArrayList<>(originals.keySet())) restore(k);
    }
}
