package __PKG__;

import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Horse;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.event.vehicle.VehicleExitEvent;
import org.bukkit.event.world.ChunkUnloadEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import java.util.function.Consumer;

/**
 * Summonable mounts that vanish when the rider gets off, quits, or the chunk unloads, so no
 * free horses pile up in the world. Mounts are tagged in PDC, which also cleans leftovers after
 * a crash (removeStray on chunk unload). One mount per player.
 * Wire: mounts = new Mounts(plugin); mounts.summon(player, h -> h.setJumpStrength(1.0)); onDisable: mounts.removeAll().
 */
public class Mounts implements Listener {

    private final NamespacedKey key;
    private final Map<UUID, UUID> riderToMount = new HashMap<>();
    private final JavaPlugin plugin;

    public Mounts(JavaPlugin plugin) {
        this.plugin = plugin;
        this.key = new NamespacedKey(plugin, "temp_mount");
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
    }

    public Horse summon(Player rider, Consumer<Horse> configure) {
        dismiss(rider.getUniqueId());
        Horse h = spawnFor(rider.getLocation(), rider.getUniqueId(), configure);
        h.setOwner(rider);
        h.addPassenger(rider);
        return h;
    }

    /** Spawns a tagged, tamed, saddled horse (no rider yet). */
    public Horse spawnFor(Location at, UUID rider, Consumer<Horse> configure) {
        Horse h = at.getWorld().spawn(at, Horse.class, x -> {
            x.setTamed(true);
            x.setAdult();
            x.getInventory().setSaddle(new ItemStack(Material.SADDLE));
            x.getPersistentDataContainer().set(key, PersistentDataType.STRING, rider.toString());
            x.setPersistent(false);
            if (configure != null) configure.accept(x);
        });
        riderToMount.put(rider, h.getUniqueId());
        return h;
    }

    public boolean isTempMount(Entity e) { return e.getPersistentDataContainer().has(key, PersistentDataType.STRING); }

    public void dismiss(UUID rider) {
        UUID id = riderToMount.remove(rider);
        if (id == null) return;
        Entity e = plugin.getServer().getEntity(id);
        if (e != null) e.remove();
    }

    public int active() { return riderToMount.size(); }

    public void removeAll() { for (UUID r : new java.util.ArrayList<>(riderToMount.keySet())) dismiss(r); }

    @EventHandler
    public void onExit(VehicleExitEvent e) {
        if (isTempMount(e.getVehicle()) && e.getExited() instanceof Player p) {
            plugin.getServer().getScheduler().runTask(plugin, () -> dismiss(p.getUniqueId()));
        }
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) { dismiss(e.getPlayer().getUniqueId()); }

    @EventHandler
    public void onUnload(ChunkUnloadEvent e) {
        for (Entity en : e.getChunk().getEntities()) if (isTempMount(en)) en.remove();
    }
}
