package __PKG__;

import org.bukkit.NamespacedKey;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Custom weapons and wands: items carry an ability id in PDC; right-click and melee-hit dispatch
 * to registered handlers, with a per-player-per-ability cooldown. Main hand only (PlayerInteractEvent
 * fires once per hand; without the hand check every ability runs twice).
 * Wire: abilities = new ItemAbilities(plugin);
 *   abilities.onUse("fire_wand", 40, (p, item) -> {...});         // right click, 2 s cooldown
 *   abilities.onHit("vampire_blade", 0, (p, target, e) -> {...}); // melee hit
 *   ItemStack wand = abilities.tag(new ItemStack(Material.BLAZE_ROD), "fire_wand");
 */
public class ItemAbilities implements Listener {

    public interface Use { void run(Player player, ItemStack item); }
    public interface Hit { void run(Player attacker, LivingEntity target, EntityDamageByEntityEvent event); }

    private final NamespacedKey key;
    private final Map<String, Use> uses = new HashMap<>();
    private final Map<String, Hit> hits = new HashMap<>();
    private final Map<String, Long> cooldownTicks = new HashMap<>();
    private final Map<String, Long> readyAt = new ConcurrentHashMap<>();

    public ItemAbilities(JavaPlugin plugin) {
        this.key = new NamespacedKey(plugin, "ability");
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
    }

    public ItemAbilities onUse(String id, long cooldown, Use u) { uses.put(id, u); cooldownTicks.put("use:" + id, cooldown); return this; }

    public ItemAbilities onHit(String id, long cooldown, Hit h) { hits.put(id, h); cooldownTicks.put("hit:" + id, cooldown); return this; }

    public ItemStack tag(ItemStack item, String abilityId) {
        ItemMeta m = item.getItemMeta();
        if (m == null) return item;
        m.getPersistentDataContainer().set(key, PersistentDataType.STRING, abilityId);
        item.setItemMeta(m);
        return item;
    }

    public String abilityOf(ItemStack item) {
        if (item == null || item.getType().isAir() || !item.hasItemMeta()) return null;
        return item.getItemMeta().getPersistentDataContainer().get(key, PersistentDataType.STRING);
    }

    /** true = may fire now (and the cooldown starts). Cooldown in ticks (50 ms). */
    public boolean ready(UUID player, String slot) {
        long cd = cooldownTicks.getOrDefault(slot, 0L) * 50L;
        if (cd <= 0) return true;
        long now = System.currentTimeMillis();
        String k = player + "|" + slot;
        Long at = readyAt.get(k);
        if (at != null && at > now) return false;
        readyAt.put(k, now + cd);
        return true;
    }

    @EventHandler(priority = EventPriority.HIGH)
    public void onInteract(PlayerInteractEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        if (e.getAction() != Action.RIGHT_CLICK_AIR && e.getAction() != Action.RIGHT_CLICK_BLOCK) return;
        ItemStack item = e.getItem();
        String id = abilityOf(item);
        Use u = id == null ? null : uses.get(id);
        if (u == null) return;
        e.setCancelled(true);
        if (ready(e.getPlayer().getUniqueId(), "use:" + id)) u.run(e.getPlayer(), item);
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onHitEntity(EntityDamageByEntityEvent e) {
        if (!(e.getDamager() instanceof Player p) || !(e.getEntity() instanceof LivingEntity target)) return;
        String id = abilityOf(p.getInventory().getItemInMainHand());
        Hit h = id == null ? null : hits.get(id);
        if (h != null && ready(p.getUniqueId(), "hit:" + id)) h.run(p, target, e);
    }
}
