package __PKG__;

import net.kyori.adventure.audience.Audience;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.sound.Sound;
import org.bukkit.Bukkit;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

import java.util.ArrayList;
import java.util.List;

/**
 * Short jingles and alarms from note-block sounds: a list of (delay, instrument, semitone) played
 * on the scheduler. Pitch follows the note-block scale: semitone 0..24 maps to pitch 0.5..2.0
 * (12 = 1.0, F#). Instruments are sound keys ("block.note_block.pling", "block.note_block.bell"),
 * so the same code runs on every 1.21.x.
 * Wire: Melody.parse("pling 0 0, pling 4 4, pling 7 4, bell 12 8").play(plugin, player);
 */
public class Melody {

    public record Note(int delayTicks, String instrument, int semitone) {}

    private final List<Note> notes;

    public Melody(List<Note> notes) { this.notes = List.copyOf(notes); }

    /** "instrument semitone delay, ..." where delay is ticks after the previous note. */
    public static Melody parse(String spec) {
        List<Note> out = new ArrayList<>();
        for (String part : spec.split(",")) {
            String[] p = part.trim().split("\\s+");
            if (p.length < 2) continue;
            try {
                int semi = Math.max(0, Math.min(24, Integer.parseInt(p[1])));
                int delay = p.length > 2 ? Math.max(0, Integer.parseInt(p[2])) : 4;
                out.add(new Note(delay, p[0], semi));
            } catch (NumberFormatException ignored) { /* skip bad note */ }
        }
        return new Melody(out);
    }

    public int size() { return notes.size(); }

    public int lengthTicks() { int t = 0; for (Note n : notes) t += n.delayTicks(); return t; }

    public static float pitch(int semitone) { return (float) Math.pow(2.0, (semitone - 12) / 12.0); }

    /** Plays to any Audience (a player, a world, Bukkit.getServer()). Returns the tasks so callers can cancel. */
    public List<BukkitTask> play(JavaPlugin plugin, Audience to) {
        List<BukkitTask> tasks = new ArrayList<>();
        long at = 0;
        for (Note n : notes) {
            at += n.delayTicks();
            String key = n.instrument().contains(".") ? n.instrument() : "block.note_block." + n.instrument();
            Sound s = Sound.sound(Key.key("minecraft", key), Sound.Source.RECORD, 1f, pitch(n.semitone()));
            if (at == 0) to.playSound(s);
            else tasks.add(Bukkit.getScheduler().runTaskLater(plugin, () -> to.playSound(s), at));
        }
        return tasks;
    }
}
