package __PKG__;

import org.bukkit.GameRule;
import org.bukkit.World;

import java.util.Locale;

/**
 * Time and weather control for /day, /night, /sun, /rain, /freezetime.
 * Time presets are ticks (day 1000, noon 6000, night 13000, midnight 18000). Clearing weather
 * sets a long clear duration so it does not rain again a minute later.
 */
public final class WorldClock {

    private WorldClock() {}

    /** "day", "noon", "night", "midnight", "sunrise", "sunset" or a tick number; -1 when invalid. */
    public static long parseTime(String s) {
        switch (s.toLowerCase(Locale.ROOT)) {
            case "sunrise": return 23000;
            case "day": return 1000;
            case "noon": return 6000;
            case "sunset": return 12000;
            case "night": return 13000;
            case "midnight": return 18000;
            default:
                try { long t = Long.parseLong(s); return t >= 0 && t < 24000 ? t : -1; } catch (NumberFormatException e) { return -1; }
        }
    }

    public static void setTime(World w, long ticks) { w.setTime(ticks); }

    public static void clearWeather(World w, int seconds) {
        w.setStorm(false);
        w.setThundering(false);
        w.setClearWeatherDuration(Math.max(20, seconds * 20));
    }

    public static void rain(World w, int seconds, boolean thunder) {
        w.setStorm(true);
        w.setWeatherDuration(Math.max(20, seconds * 20));
        w.setThundering(thunder);
        if (thunder) w.setThunderDuration(Math.max(20, seconds * 20));
    }

    /** Freezes or unfreezes the day/night cycle. */
