"use strict";
// Cyrus Pattern Library: loading, hashing, status, retrieval (service 0.6).
//
// Patterns are small verified building blocks (see library/<game>/patterns/<id>/pattern.json and
// lib/cyrus/library/types.ts for the schema). The CLI tools/library.js builds library/<game>.json
// from the sources + library/<game>/verify.json; the service only reads the built file.
//
// Retrieval design (MB_LIBRARY, default "off" until the A/B eval says otherwise):
//   off    nothing changes: system prompt byte-identical to 0.5, no files placed.
//   index  a compact index of the patterns verified for this version goes at the END of the cached
//          system prompt (byte-identical per version + library version, so it is cached across
//          builds like the sheet), and the pattern files are placed read-only in the workspace
//          (.cyrus-library/) so the model can Read the ones it wants. Nothing else is injected.
//   auto   index + deterministic selection: up to MB_LIBRARY_MAX (3) RARE patterns whose triggers
//          match the request strongly are inlined in the USER turn (after the cached prefix, so
//          the prefix cache is untouched). COMMON-API patterns are never inlined (CloudAPIBench:
//          retrieval for APIs the model already knows can hurt), only indexed.
// The files are removed from the workspace before compiling; only what the model wrote into
// src/ is built, scanned and shipped, exactly as before.

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const LIB_DIR = process.env.MB_LIBRARY_DIR || path.join(__dirname, "library");
const MODE = ["off", "index", "auto"].includes(process.env.MB_LIBRARY || "") ? process.env.MB_LIBRARY : "off";
const MAX_INJECT = Math.max(0, parseInt(process.env.MB_LIBRARY_MAX || "3", 10) || 0);
const MAX_INJECT_TOKENS = Math.max(0, parseInt(process.env.MB_LIBRARY_MAX_TOKENS || "3500", 10) || 0);
const MIN_SCORE = 2;
const WS_DIR = ".cyrus-library";

const NOTICE_REQUIRED = new Set(["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC"]);
const ALLOWED = {
  nxeon: ["LicenseRef-Nxeon-Authored"],
  "opted-in-build": ["LicenseRef-Cyrus-Contributor-Grant"],
  "third-party": ["MIT-0", "0BSD", "CC0-1.0", "Unlicense", "MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC"],
};

// ------------------------------------------------------------- sources ----
function readSources(game, dir = LIB_DIR) {
  const root = path.join(dir, game, "patterns");
  if (!fs.existsSync(root)) return [];
  const out = [];
  for (const id of fs.readdirSync(root).sort()) {
    const pdir = path.join(root, id);
    if (!fs.statSync(pdir).isDirectory()) continue;
    const meta = JSON.parse(fs.readFileSync(path.join(pdir, "pattern.json"), "utf8"));
    const files = fs.readdirSync(pdir).filter((f) => f !== "pattern.json" && !f.startsWith(".")).sort()
      .map((f) => ({ path: f, code: fs.readFileSync(path.join(pdir, f), "utf8") }));
    out.push({ ...meta, game, files, _dir: pdir });
  }
  return out;
}

/** Canonical JSON (sorted keys) so the hash does not depend on key order or whitespace. */
function canon(x) {
  if (Array.isArray(x)) return `[${x.map(canon).join(",")}]`;
  if (x && typeof x === "object") return `{${Object.keys(x).sort().map((k) => `${JSON.stringify(k)}:${canon(x[k])}`).join(",")}}`;
  return JSON.stringify(x);
}

/** sha256 over everything that defines the pattern and its test (not the verification records). */
function contentHash(p) {
  const { _dir, verification, status, verifiedOn, contentHash: _h, tokens, ...rest } = p;
  return crypto.createHash("sha256").update(canon(rest)).digest("hex");
}

const tokensOf = (files) => Math.ceil(files.reduce((a, f) => a + f.code.length, 0) / 3.5);

function statusOf(p, recs) {
  const per = {};
  for (const v of p.versions) {
    const r = recs && recs[v];
    if (!r || r.contentHash !== p.contentHash) { per[v] = "unverified"; continue; }
    if (r.compile !== "pass" || r.scan === "block" || r.runtime === "fail") per[v] = "failing";
    else if (r.scan !== "pass") per[v] = "failing";
    else if (r.runtime === "pass") per[v] = "verified";
    else per[v] = "compiled";
  }
  const vals = Object.values(per);
  let status = "unverified";
  if (vals.includes("failing")) status = "failing";
  else if (vals.length && vals.every((s) => s === "verified")) status = "verified";
  else if (vals.length && vals.every((s) => s === "verified" || s === "compiled")) status = "compiled";
  return { status, verifiedOn: Object.keys(per).filter((v) => per[v] === "verified"), per };
}

/** Builds the library object (what library/<game>.json holds). */
function build(game, { dir = LIB_DIR, gameVersions = [], previous = null } = {}) {
  const verifyFile = path.join(dir, game, "verify.json");
  const verify = fs.existsSync(verifyFile) ? JSON.parse(fs.readFileSync(verifyFile, "utf8")) : {};
  const removedFile = path.join(dir, game, "removed.json");
  const removed = fs.existsSync(removedFile) ? JSON.parse(fs.readFileSync(removedFile, "utf8")) : [];
  const gone = new Set(removed.map((r) => r.id));
  const patterns = readSources(game, dir).filter((p) => !gone.has(p.id)).map((src) => {
    const { _dir, ...p } = src;
    p.contentHash = contentHash(p);
    p.tokens = tokensOf(p.files);
    const recs = verify[p.id] || {};
    p.verification = p.versions.map((v) => recs[v]).filter(Boolean);
    const st = statusOf(p, recs);
    p.status = st.status;
    p.verifiedOn = st.verifiedOn;
    return p;
  });
  const fingerprint = crypto.createHash("sha256").update(patterns.map((p) => `${p.id}:${p.contentHash}:${p.status}:${p.verifiedOn.join(",")}`).join("|")).digest("hex").slice(0, 10);
  const version = previous && previous.fingerprint === fingerprint ? previous.version : `lib-${fingerprint}`;
  return { game, version, fingerprint, builtAt: previous && previous.fingerprint === fingerprint ? previous.builtAt : new Date().toISOString(), gameVersions, patterns, removed };
}

// ------------------------------------------------------------- runtime ----
const LOADED = {};
function load(game = "minecraft") {
  if (game in LOADED) return LOADED[game];
  try { LOADED[game] = JSON.parse(fs.readFileSync(path.join(LIB_DIR, `${game}.json`), "utf8")); }
  catch { LOADED[game] = null; }
  return LOADED[game];
}

/** Patterns usable for a game version: verified on it (never draft/failing/unverified ones). */
function usable(lib, version) {
  if (!lib) return [];
  return lib.patterns.filter((p) => p.verifiedOn.includes(version));
}

function libraryVersion(game = "minecraft") {
  const lib = load(game);
  return MODE === "off" || !lib ? "nolib" : `${lib.version}:${MODE}`;
}

/** The index block for the cached system prompt. Byte-identical for a given library + version. */
function indexText(version, lib = load("minecraft"), mode = MODE) {
  if (mode === "off") return "";
  const ps = usable(lib, version).slice().sort((a, b) => a.id.localeCompare(b.id));
  if (!ps.length) return "";
  const lines = ps.map((p) => `- ${p.id} [${p.category}]: ${p.summary}`);
  return `\n\nVERIFIED PATTERN LIBRARY (${ps.length} building blocks; each compiled against this exact Paper ${version} jar and loaded on a real Paper ${version} server). On a new plugin you MAY Read ${WS_DIR}/<id>/*.java for any you need (Read them all in your first response, with nothing else) and copy them into your package (replace \`package __PKG__;\`, rename freely, keep the logic). Only use one when it really fits the request; small and correct beats big. Never edit ${WS_DIR}.\n${lines.join("\n")}`;
}

function words(s) { return ` ${String(s || "").toLowerCase().replace(/[^a-z0-9/|+\s.-]/g, " ").replace(/\s+/g, " ")} `; }

/** Deterministic scores for every usable pattern against the request text (higher = better). */
function score(text, version, lib = load("minecraft")) {
  const t = words(text);
  return usable(lib, version).map((p) => {
    let s = 0;
    const hits = [];
    for (const trig of p.triggers || []) {
      const w = words(trig).trim();
      if (!w) continue;
      if (t.includes(` ${w} `) || (w.length >= 6 && t.includes(w))) { s += w.includes(" ") ? 2 : 1; hits.push(trig); }
    }
    for (const tag of p.tags || []) {
      const w = tag.replace(/-/g, " ");
      if (t.includes(` ${w} `)) { s += 1; hits.push(`#${tag}`); }
    }
    return { id: p.id, score: s, hits, frequency: p.frequency, retrieval: p.retrieval, tokens: p.tokens };
  }).filter((x) => x.score > 0).sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
}

/** Which patterns to inline for this request (mode "auto" only). Rare + auto + strong match, token-capped. */
function select(text, version, lib = load("minecraft"), { max = MAX_INJECT, maxTokens = MAX_INJECT_TOKENS } = {}) {
  const picked = [];
  let tokens = 0;
  for (const c of score(text, version, lib)) {
    if (picked.length >= max) break;
    if (c.score < MIN_SCORE || c.frequency !== "rare" || c.retrieval !== "auto") continue;
    const p = lib.patterns.find((x) => x.id === c.id);
    const extra = (p.requires || []).filter((r) => !picked.includes(r));
    const add = [c.id, ...extra].filter((id, i, a) => a.indexOf(id) === i && !picked.includes(id));
    const cost = add.reduce((a, id) => a + (lib.patterns.find((x) => x.id === id) || { tokens: 0 }).tokens, 0);
    if (tokens + cost > maxTokens) continue;
    picked.push(...add);
    tokens += cost;
  }
  return { ids: picked, tokens };
}

/** User-turn block with the selected patterns' code. */
function injectBlock(ids, version, lib = load("minecraft")) {
  if (!ids.length) return "";
  const parts = ids.map((id) => {
    const p = lib.patterns.find((x) => x.id === id);
    const files = p.files.map((f) => `--- ${f.path}\n${f.code.trim()}`).join("\n");
    return `## ${p.id}: ${p.title}\nUse: ${p.usage}\n${files}`;
  });
  return `\nVERIFIED PATTERNS FOR THIS REQUEST (picked automatically; compiled and loaded on Paper ${version}). Reuse them where they fit by copying into your package (replace \`package __PKG__;\`); they are already in ${WS_DIR}/, so do not Read them again:\n${parts.join("\n\n")}\n`;
}

/** Places every usable pattern under <ws>/.cyrus-library/<id>/ for on-demand Reads. */
function place(ws, version, lib = load("minecraft")) {
  const ps = usable(lib, version);
  for (const p of ps) {
    const d = path.join(ws, WS_DIR, p.id);
    fs.mkdirSync(d, { recursive: true });
    for (const f of p.files) fs.writeFileSync(path.join(d, f.path), f.code);
  }
  return ps.length;
}

function drop(ws) { fs.rmSync(path.join(ws, WS_DIR), { recursive: true, force: true }); }

/** NOTICE text for attribution-required third-party patterns the build was given (may be ""). */
function noticesFor(ids, lib = load("minecraft")) {
  if (!lib) return "";
  const out = [];
  for (const id of ids) {
    const p = lib.patterns.find((x) => x.id === id);
    if (!p || p.source.kind !== "third-party" || !NOTICE_REQUIRED.has(p.source.license)) continue;
    out.push(`${p.id} (${p.source.license}${p.source.modified ? ", modified" : ""}) from ${p.source.url} @ ${p.source.commit}\n${p.source.attribution}`);
  }
  return out.length ? `This plugin may contain code adapted from the following sources:\n\n${out.join("\n\n")}\n` : "";
}

module.exports = {
  MODE, WS_DIR, ALLOWED, NOTICE_REQUIRED, readSources, canon, contentHash, tokensOf, statusOf, build, load, usable,
  libraryVersion, indexText, score, select, injectBlock, place, drop, noticesFor,
};

