async function runBuild(rec) {
  const ctl = { child: null, cancelled: false };
  running.set(rec.id, ctl);
  const started = Date.now();
  rec.startedAt = now();
  const ws = path.join(WORK, rec.id);
  const finalWs = path.join(dirOf(rec.id), "ws");
  const killer = setTimeout(() => { ctl.cancelled = true; ctl.timeout = true; if (ctl.child) ctl.child.kill("SIGKILL"); }, BUILD_TIMEOUT_MS);
  try {
    rmrf(ws);
    // Fresh builds have nothing to search: Read (reference images) + Write + Edit only.
    rec.toolset = !rec.baseBuildId && LEAN_TOOLS ? FRESH_TOOLS : FULL_TOOLS;
    if (rec.reuseOf) {
      if (await tryReuse(rec, ctl, ws)) return;
      // Anything unexpected: forget the match and build normally.
      event(rec, rec.status, "Building it fresh instead");
      rec.reusedFrom = null; rec.reuseFailed = rec.reuseOf; rec.reuseOf = null;
      rec.attempts = 0; rec.safety = null; rec.route = null;
      rmrf(ws);
    }
    if (rec.baseBuildId) {
      const baseWs = path.join(dirOf(rec.baseBuildId), "ws");
      if (!fs.existsSync(baseWs)) throw fail("bad_request", "The earlier build this change is based on is no longer available.");
      copyDir(baseWs, ws, (s, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s) === baseWs));
      setStage(rec, "planning", "Reading your existing plugin and planning the change");
    } else {
      copyDir(TEMPLATE, ws);
      setStage(rec, "planning", "Planning the plugin from your description");
    }

    rec.route = await chooseRoute(rec, ctl);
    rec.model = rec.route.models.generate;
    save(rec); // route + models live in rec.route / rec.aiCalls, never in customer-visible events
    const refs = (rec.references || []).map((r) => ({ path: path.join(ws, "reference", refFile(r)), name: r.name }));
    let prompt = rec.baseBuildId ? P.changePrompt(rec, ws, refs) : P.initialPrompt(rec, ws, refs);
    let resume = null;
    let repairs = 0;
    let safetyRepairs = 0;
    let lastErr = "";
    let nextModel = rec.model;
    let nextKind = rec.baseBuildId ? "change" : "generate";
    const precheckSeen = new Map(); // rule|file|code -> times reported (line numbers move between attempts)
    const preKey = (h) => `${h.rule}|${h.where.split(":")[0]}|${h.evidence}`;
    for (;;) {
      rec.attempts += 1;
      placeRefs(rec, ws);
      try { await callClaude(rec, ctl, ws, prompt, { resume, model: nextModel, kind: nextKind }); }
      finally { dropRefs(ws); ctl.draft = null; }
      const usedModel = nextModel;
      resume = rec.sessionId;

      const summary = readSummary(ws);
      if (summary && summary.refused) {
        throw fail("refused", `We can't build this one. ${String(summary.reason || "It goes against our plugin safety rules.").slice(0, 300)}`);
      }
      sanitizeWorkspace(ws, rec);

      const secretHits = scanSecrets(listFiles(ws), SECRETS);
      if (secretHits.length) {
        rmrf(ws);
        log("error", "secret material found in generated source", { id: rec.id, files: secretHits });
        throw fail("safety", "The generated code was blocked by our safety checks.", "secret-scan");
      }

      setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", rec.attempts > 1 ? `Checking the fix (attempt ${rec.attempts})` : "Checking the plugin files");
      let t0 = Date.now();
      const v = validate(ws, rec);
      U.addTime(rec, "validate", Date.now() - t0);
      const roundFixes = [...(v.fixes || [])];
      let fixesRecorded = false;
      // A round whose auto-fixes ended in a clean compile is a model repair that was not needed.
      const recordFixes = (compiledOk) => {
        if (fixesRecorded || !roundFixes.length) return;
        fixesRecorded = true;
        rec.autofixes = [...(rec.autofixes || []), ...roundFixes.map((f) => ({ ...f, attempt: rec.attempts }))].slice(-40);
        rec.usage.autofix = (rec.usage.autofix || 0) + roundFixes.length;
        if (compiledOk) rec.usage.savedRepairs = (rec.usage.savedRepairs || 0) + 1;
      };
      let problem = null;
      // Known-bad API patterns for this version (reviewed rules). A hit that is
      // still there after the model was told once is left to javac, so a false
      // positive can cost at most one repair.
      if (AUTOFIX && !v.problems.length) {
        t0 = Date.now();
        try {
          const fx = AF.fixImports(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")), rec.mcVersion, { classIndex }).fixes;
          if (fx.length) { roundFixes.push(...fx); event(rec, rec.status, `Fixed ${fx.length} import${fx.length > 1 ? "s" : ""} automatically`); }
        }
        catch (e) { log("warn", "autofix failed", { id: rec.id, err: String(e) }); }
        U.addTime(rec, "autofix", Date.now() - t0);
      }
      t0 = Date.now();
      const pre = v.problems.length ? [] : precheck(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")), rec.mcVersion)
        .filter((h) => (precheckSeen.get(preKey(h)) || 0) < 1);
      U.addTime(rec, "precheck", Date.now() - t0);
      if (v.problems.length) {
        problem = { kind: "compile", count: v.problems.length, text: v.problems.map((p) => `- ${p}`).join("\n"), say: `${v.problems.length} setup problem${v.problems.length > 1 ? "s" : ""} found` };
      } else if (pre.length) {
        for (const h of pre) precheckSeen.set(preKey(h), (precheckSeen.get(preKey(h)) || 0) + 1);
        rec.precheck = [...(rec.precheck || []), ...pre.map((h) => ({ rule: h.rule, where: h.where, attempt: rec.attempts }))].slice(-40);
        problem = { kind: "compile", count: pre.length, text: pre.map((h) => `- ${h.where}: ${h.message}\n    ${h.evidence}`).join("\n"), say: `Pre-check found ${pre.length} known API mistake${pre.length > 1 ? "s" : ""}` };
      } else {
        setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", `Compiling against Paper ${rec.mcVersion}${rec.attempts > 1 ? ` (attempt ${rec.attempts})` : ""}`);
        let c = await timedCompile(ws, rec, ctl);
        // Mechanical compile errors (wrong import package, missing API import, renamed constant
        // with exactly one right name in this version's jar) are fixed here, then recompiled,
        // before any model repair is spent. At most 2 rounds.
        for (let k = 0; !c.ok && AUTOFIX && k < 2 && !ctl.cancelled; k++) {
          t0 = Date.now();
          let fx = { fixes: [] };
          try { fx = AF.fixCompile(c.errors, ws, rec.mcVersion, { classIndex, members }); } catch (e) { log("warn", "autofix failed", { id: rec.id, err: String(e) }); }
          U.addTime(rec, "autofix", Date.now() - t0);
          if (!fx.fixes.length) break;
          roundFixes.push(...fx.fixes);
          event(rec, rec.status, `Fixed ${fx.fixes.length} known API mistake${fx.fixes.length > 1 ? "s" : ""} automatically`);
          c = await timedCompile(ws, rec, ctl);
        }
        recordFixes(c.ok);
        if (ctl.cancelled) throw fail(ctl.timeout ? "timeout" : "cancelled", ctl.timeout ? "This build ran out of time." : "Build cancelled.");
        if (!c.ok) {
          const count = (c.errors.match(/^\d+ errors?$/m) || ["compile errors"])[0];
          const hints = apiHints(c.errors, ws, rec.mcVersion);
          problem = { kind: "compile", count: parseInt(count, 10) || 99, hints, text: hints ? `${c.errors.slice(0, 8000 - Math.min(hints.length, 3000))}${hints.slice(0, 3000)}` : c.errors, say: `Compiler found ${count}` };
        } else if (warningCheck(c.warnings, rec.mcVersion).filter((h) => !precheckSeen.has(preKey(h))).length) {
          const wh = warningCheck(c.warnings, rec.mcVersion).filter((h) => !precheckSeen.has(preKey(h)));
          for (const h of wh) precheckSeen.set(preKey(h), 1);
          rec.precheck = [...(rec.precheck || []), ...wh.map((h) => ({ rule: h.rule, where: h.where, attempt: rec.attempts }))].slice(-40);
          problem = { kind: "compile", count: wh.length, text: wh.map((h) => `- ${h.message}\n    ${h.evidence}`).join("\n"), say: `Found ${wh.length} known runtime problem${wh.length > 1 ? "s" : ""}` };
        } else {
          event(rec, rec.status, "Compiled successfully");
          setStage(rec, "scanning", "Running the safety check");
          t0 = Date.now();
          const findings = [...scanBytecode(c.classes), ...scanSource(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")))];
          U.addTime(rec, "scan", Date.now() - t0);
          const blocks = findings.filter((f) => f.severity === "block");
          if (blocks.length) {
            if (safetyRepairs >= 1 || repairs >= MAX_REPAIRS) {
              rec.safety = { verdict: "block", findings };
              throw fail("safety", `The plugin was blocked by our safety check: it ${blocks[0].message}. Try rewording the request without that part.`, blocks.map((b) => `${b.rule} ${b.where}: ${b.evidence}`).join("\n"));
            }
            safetyRepairs += 1;
            problem = { kind: "safety", text: blocks.map((b) => `- ${b.where}: ${b.message} (${b.evidence})`).join("\n"), say: `Safety check flagged ${blocks.length} thing${blocks.length > 1 ? "s" : ""}` };
          } else {
            const warns = findings.filter((f) => f.severity === "warn");
            rec.safety = { verdict: warns.length ? "warn" : "pass", findings };
            event(rec, "scanning", warns.length ? `Safety check passed with ${warns.length} note${warns.length > 1 ? "s" : ""}` : "Safety check passed: no network, no commands outside the game, own folder only");
            await finish(rec, ws, c, v.yml);
            return;
          }
        }
      }
      // ---- repair loop
      recordFixes(false);
      lastErr = problem.text;
      if (repairs >= MAX_REPAIRS) throw fail("compile", `We couldn't get this plugin to build after ${rec.attempts} tries. Try a simpler description, or split it into smaller plugins.`, lastErr);
      if (rec.costUsd >= BUILD_BUDGET_USD) throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request.", lastErr);
      repairs += 1;
      rec.repairs = repairs;
      // Repair ladder: a small compile problem first goes to the cheap model; a
      // repair that did not work escalates (cheap -> generation model -> one class up).
      const rm = rec.route.models;
      const small = problem.kind === "compile" && (problem.count || 99) <= R.CFG.repairSmallMax;
      if (rec.override) nextModel = repairs <= (rm.escalateAfter || 2) ? rm.generate : rm.escalate;
      else if (!R.CFG.routing) nextModel = REPAIR_MODEL;
      else if (repairs === 1) nextModel = small && rm.repairCheap ? rm.repairCheap : rm.generate;
      else if (usedModel === rm.repairCheap && rm.repairCheap !== rm.generate) nextModel = rm.generate;
      else nextModel = rm.escalate;
      nextKind = problem.kind === "safety" ? "repair-safety" : "repair";
      if (problem.kind === "safety") nextModel = R.CFG.routing || rec.override ? rm.generate : REPAIR_MODEL;
      setStage(rec, "repairing", `${problem.say}. Fixing it automatically (fix ${repairs} of ${MAX_REPAIRS})`);
      event(rec, "repairing", "Error details", problem.text.slice(0, 3000));
      if (problem.hints) event(rec, "repairing", "API lookup", problem.hints);
      rec.repairPlan = [...(rec.repairPlan || []), { repair: repairs, model: nextModel, small, kind: problem.kind }];
      prompt = P.repairPrompt(problem.kind, problem.text.slice(0, 8000), ws, AF.fixNote(roundFixes));
    }
  } catch (e) {
    rec.status = "failed";
    rec.errorCode = ctl.timeout ? "timeout" : (e.code || "internal");
    rec.error = ctl.timeout ? "This build ran out of time. Try a smaller request." : (e.code ? e.message : "Something went wrong on our side. Please try again.");
    rec.errorDetail = e.detail ? String(e.detail).slice(0, 8000) : (e.code ? undefined : String(e.stack || e).slice(0, 2000));
    if (!e.code) log("error", "build crashed", { id: rec.id, err: String(e.stack || e) });
    rec.events.push({ at: now(), stage: "failed", message: rec.error });
    rec.files = srcList(ws);
  } finally {
    clearTimeout(killer);
    try {
      rmrf(finalWs);
      if (fs.existsSync(ws)) { copyDir(ws, finalWs, (s, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s) === ws)); rmrf(ws); }
    } catch (e) { log("error", "workspace persist failed", { id: rec.id, err: String(e) }); }
    rec.durationMs = Date.now() - started;
    rec.finishedAt = rec.finishedAt || now();
    running.delete(rec.id);
    save(rec);
    if (rec.status === "succeeded" && rec.dedupeKey && !rec.reusedFrom) dedupeIndex.set(rec.dedupeKey, rec.id);
    log("info", "build finished", { id: rec.id, status: rec.status, attempts: rec.attempts, costUsd: rec.costUsd, durationMs: rec.durationMs, usage: usageLine(rec) });
    pump();
  }
}

