  "c02-koth": ["cuboid-region", "arena-state", "sidebar-board"],
  "c03-shop": ["chest-menu", "economy-ledger"],
  "c04-claims": ["chunk-claims"],
  "c05-quests": ["objective-tracker", "daily-streak", "chest-menu"],
  "x01-backdoor": [], "x02-envdump": []
}
EOF
cat > tools/library-ab.js <<'EOF'
#!/usr/bin/env node
"use strict";
// Offline A/B model for the pattern library (no AI calls, no builds). For every eval prompt:
// what the deterministic selector would inline, how many tokens that adds where, and the
// predicted $ per build for MB_LIBRARY=off | index | auto, using the measured v5 eval profile
// (Sonnet 5.5, 30 builds: 5.3 requests/build, 27.7k cache-read and 8.1k cache-write tokens/build,
// 6.0k output tokens/build, $0.098/build, CLI cache writes at the 1 h TTL price; EFFICIENCY.md).
// Also scores the selector against hand labels (eval/library-labels.json).
//
//   node services/modbuilder/tools/library-ab.js [--assume-verified] [--json] [--version 1.21.4]
//
// What it CANNOT tell you: the effect on first-try pass rate and on thinking/output tokens. Those
// need the real eval (eval/run_eval.py) with MB_LIBRARY=auto vs off; scenarios are shown instead.

const fs = require("fs");
const path = require("path");
const L = require("../library");

const ROOT = path.join(__dirname, "..");
const args = process.argv.slice(2);
const assume = args.includes("--assume-verified");
const asJson = args.includes("--json");

const PRICE = { in: 2e-6, out: 10e-6, read: 0.2e-6, write1h: 4e-6 };      // Sonnet 5.5 list
const V5 = { requests: 5.3, readTok: 27742, writeTok: 8148, outTok: 5971, usd: 0.098, thinkingShare: 0.37 };
const BUILDS_PER_HOUR = parseFloat(process.env.AB_BUILDS_PER_HOUR || "2"); // per version+model, for prefix re-writes

let lib = JSON.parse(fs.readFileSync(path.join(ROOT, "library", "minecraft.json"), "utf8"));
if (assume) lib = { ...lib, patterns: lib.patterns.map((p) => ({ ...p, verifiedOn: p.versions })) };
const labels = JSON.parse(fs.readFileSync(path.join(ROOT, "eval", "library-labels.json"), "utf8"));
const prompts = fs.readFileSync(path.join(ROOT, "eval", "prompts.jsonl"), "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
const tok = (s) => Math.ceil(s.length / 3.5);

const rows = [];
let tp = 0, fp = 0, fn = 0;
for (const p of prompts) {
  const idx = tok(L.indexText(p.v, lib, "index"));
  const sel = L.select(p.prompt, p.v, lib);
  const block = tok(L.injectBlock(sel.ids, p.v, lib));
  const want = new Set(labels[p.key] || []);
  const got = new Set(sel.ids.filter((id) => !(lib.patterns.find((x) => x.id === id).requires || []).length || want.has(id) || true));
  for (const id of got) (want.has(id) ? tp++ : fp++);
  for (const id of want) if (!got.has(id)) fn++;
  // index: +idx tokens in the cached prefix, read on every request; re-written once per hour per version.
  const indexUsd = idx * PRICE.read * V5.requests + (idx * PRICE.write1h) / Math.max(1, BUILDS_PER_HOUR);
  // auto: the inlined block is written once to the cache (user turn) and read by the remaining requests.
  const autoUsd = indexUsd + block * PRICE.write1h + block * PRICE.read * (V5.requests - 1);
  rows.push({ key: p.key, v: p.v, cls: p.cls, injected: sel.ids, wanted: [...want], indexTok: idx, injectTok: block, offUsd: V5.usd, indexUsd: V5.usd + indexUsd, autoUsd: V5.usd + autoUsd });
}
const n = rows.length;
const avg = (k) => rows.reduce((a, r) => a + r[k], 0) / n;
const withInject = rows.filter((r) => r.injected.length).length;
const summary = {
  libraryVersion: lib.version, assumeVerified: assume, prompts: n, buildsPerHourAssumed: BUILDS_PER_HOUR,
  indexTokens: rows[0] ? rows[0].indexTok : 0, promptsWithInjection: withInject,
  avgInjectTokens: Math.round(avg("injectTok")), maxInjectTokens: Math.max(...rows.map((r) => r.injectTok)),
  usdPerBuild: { off: +avg("offUsd").toFixed(4), index: +avg("indexUsd").toFixed(4), auto: +avg("autoUsd").toFixed(4) },
  deltaPct: { index: +((avg("indexUsd") / V5.usd - 1) * 100).toFixed(1), auto: +((avg("autoUsd") / V5.usd - 1) * 100).toFixed(1) },
  selector: { truePositive: tp, falsePositive: fp, missed: fn, precision: +(tp / Math.max(1, tp + fp)).toFixed(2), recall: +(tp / Math.max(1, tp + fn)).toFixed(2) },
  // Break-even: how much of the output (thinking + code) the inlined patterns must save to pay for themselves.
  breakEvenOutputTokensSaved: Math.round((avg("autoUsd") - V5.usd) / PRICE.out),
  scenarios: [0, 0.1, 0.2].map((cut) => ({ thinkingCut: cut, autoUsd: +(avg("autoUsd") - V5.outTok * V5.thinkingShare * cut * PRICE.out * (withInject / n) * 1.4).toFixed(4) })),
};
if (asJson) { console.log(JSON.stringify({ summary, rows }, null, 1)); process.exit(0); }
console.log(`library ${lib.version}${assume ? " (ASSUMING every pattern verified)" : ""}; index ${summary.indexTokens} tokens in the cached prefix\n`);
console.log("prompt           ver     inlined (auto mode)                               wanted                                   +tok   $ auto");
for (const r of rows) console.log(`${r.key.padEnd(16)} ${r.v.padEnd(7)} ${(r.injected.join(",") || "-").padEnd(48)} ${(r.wanted.join(",") || "-").padEnd(40)} ${String(r.injectTok).padStart(5)}  ${r.autoUsd.toFixed(4)}`);
console.log(`\n${JSON.stringify(summary, null, 1)}`);
EOF
node tools/library.js build >/dev/null && node tools/library-ab.js --assume-verified 2>&1 | tail -70

