/**
 * A chest menu identified by its InventoryHolder (never by title: players can rename chests).
 * Buttons are slot -> action. MenuListener cancels EVERY click and drag while a Menu is the top
 * inventory (including shift-click, number keys, double-click collect and clicks in the player's
 * own inventory), which closes the classic item-duplication holes.
 * Wire: register MenuListener once; then
 *   Menu m = new Menu(27, Component.text("Warps")); m.button(10, item, e -> ...); m.open(player);
 */
public class Menu implements InventoryHolder {
  public Menu(int size, Component title);
  public Menu button(int slot, ItemStack icon, Consumer<InventoryClickEvent> action);
  public Menu fill(ItemStack filler);
  public Menu clear();
  public Menu onClose(Consumer<Player> callback);
  public void open(Player player);
  public boolean hasAction(int slot);
}
===== library/minecraft/patterns/arena-state/Arena.java 1168 -> 321
/**
 * Minigame round lifecycle as an explicit state machine:
 * WAITING -(min players)-> COUNTDOWN -(timer)-> RUNNING -(end())-> ENDING -(delay)-> WAITING.
 * Players are tracked by UUID; leave() is the ONE place a player is cleaned up (call it from
 * quit, kick, death-elimination and end), so nobody is left with arena items/effects.
 * Hooks are plain callbacks: onStart, onEnd (winner may be null), onLeave(player) for cleanup.
 * Wire: listener for PlayerQuitEvent -> arena.leave(player). onDisable -> arena.shutdown().
 */
public class Arena {
  public enum State {
    WAITING, COUNTDOWN, RUNNING, ENDING
  }
  public Consumer<Arena> onStart;
  public Consumer<UUID> onEnd;
  public Consumer<Player> onLeave;
  public Consumer<Integer> onCountdown;
  public Arena(JavaPlugin plugin, String name, int minPlayers, int maxPlayers, int countdownSeconds);
  public String name();
  public State state();
  public Set<UUID> players();
  public boolean contains(UUID id);
  public boolean join(UUID id);
  public void leave(UUID id);
  public void forceStart();
  public void end(UUID winner);
  public void shutdown();
}
