/**
 * Balances in whole minor units (long "cents"), never double (0.1 + 0.2 != 0.3), with overflow
 * checks and no negative balances. Every change goes through one synchronized method, so /pay
 * from two places at once cannot duplicate money. Persist with save()/load() on change + on a
 * timer + in onDisable.
 * Display: Ledger.format(12345, 2) -> "123.45".
 */
public class Ledger {
  public enum Result {
    OK, INSUFFICIENT_FUNDS, INVALID_AMOUNT, SAME_ACCOUNT, OVERFLOW
  }
  public Ledger(long startingBalance);
  public long balance(UUID id);
  public boolean isDirty();
  public synchronized Result deposit(UUID id, long amount);
  public synchronized Result withdraw(UUID id, long amount);
  public synchronized Result set(UUID id, long amount);
  public synchronized Result transfer(UUID from, UUID to, long amount);
  public List<Map.Entry<UUID, Long>> top(int n);
  public static Long parse(String text, int decimals);
  public static String format(long minor, int decimals);
  public synchronized void save(YamlConfiguration y);
  public synchronized void load(YamlConfiguration y);
}
