/**
 * Cyrus Pattern Library: status + drift for the lifecycle agent (PURE, no fs; server or client).
 *
 * The lifecycle agent's "your mod may be out of date" logic asks two questions here:
 *   1. Is a pattern still good on a game version?           patternStatus(lib, id, version)
 *   2. A mod was built from patterns P on version A; the server now runs B (or a new game version
 *      B came out). What breaks?                            modLibraryRisk(lib, P, B, drift?)
 * `drift` is a re-verify report (services/modbuilder/library/minecraft/drift-<B>.json, written by
 * `node services/modbuilder/tools/library.js drift <B>` on node-2) for versions the library does
 * not claim yet. Builds record the patterns they used in the build record's
 * `library.usedPatterns` (attach mode) or `library.injected` (auto mode).
 */
import type { LibraryPattern, PatternLibrary, PatternStatus } from "./types";
import minecraftJson from "../../../services/modbuilder/library/minecraft.json";

export const minecraftLibrary = minecraftJson as unknown as PatternLibrary;

export type DriftReport = {
  version: string;
  date: string;
  apiJar: string;
  server?: string;
  patterns: Record<string, { contentHash: string; compile: "pass" | "fail"; scan: "pass" | "block"; runtime?: "pass" | "fail"; warnings: number; errors?: string; runtimeDetail?: string }>;
  broken: string[];
};

export type VersionStatus = PatternStatus | "not-claimed" | "unknown-pattern";

/** The pattern's status on ONE version (the library-level `status` covers all claimed versions). */
export function patternStatus(lib: PatternLibrary, id: string, version: string): VersionStatus {
  const p = lib.patterns.find((x) => x.id === id);
  if (!p) return lib.removed.some((r) => r.id === id) ? "unverified" : "unknown-pattern";
  if (!p.versions.includes(version)) return "not-claimed";
  if (p.verifiedOn.includes(version)) return "verified";
  const r = p.verification.find((x) => x.version === version);
  if (!r || r.contentHash !== p.contentHash) return "unverified";
  if (r.compile !== "pass" || r.scan !== "pass" || r.runtime === "fail") return "failing";
  return "compiled";
}

export type LibraryHealth = { version: string; total: number; verified: number; compiled: number; failing: number; unverified: number };

export function libraryHealth(lib: PatternLibrary): LibraryHealth[] {
  return lib.gameVersions.map((version) => {
    const h: LibraryHealth = { version, total: 0, verified: 0, compiled: 0, failing: 0, unverified: 0 };
    for (const p of lib.patterns) {
      if (!p.versions.includes(version)) continue;
      h.total++;
      const s = patternStatus(lib, p.id, version);
      if (s === "verified" || s === "compiled" || s === "failing" || s === "unverified") h[s]++;
    }
    return h;
  });
}

export type LibraryRisk = {
  patternId: string;
  level: "ok" | "warn" | "error";
  /** Plain words for the owner/creator (lifecycle agent shows them). */
  message: string;
};

/**
 * Risk for a mod that used `patternIds`, when it runs on `version`. Uses the library's own records
 * when the version is claimed, else the drift report for that version, else "unknown" (warn).
 */
export function modLibraryRisk(lib: PatternLibrary, patternIds: string[], version: string, drift?: DriftReport | null): LibraryRisk[] {
  return [...new Set(patternIds)].map((id): LibraryRisk => {
    const p: LibraryPattern | undefined = lib.patterns.find((x) => x.id === id);
    const title = p ? p.title : id;
    if (!p) {
      return lib.removed.some((r) => r.id === id)
        ? { patternId: id, level: "ok", message: `"${id}" was withdrawn from the library; the copy inside this mod is unchanged.` }
        : { patternId: id, level: "warn", message: `Unknown library building block "${id}".` };
    }
    if (p.versions.includes(version)) {
      const s = patternStatus(lib, id, version);
      if (s === "verified") return { patternId: id, level: "ok", message: `${title}: verified on ${version}.` };
      if (s === "failing") return { patternId: id, level: "error", message: `${title} no longer passes verification on ${version}; mods built with it may break there.` };
      return { patternId: id, level: "warn", message: `${title} has not been re-verified on ${version} yet.` };
    }
    const d = drift && drift.version === version ? drift.patterns[id] : undefined;
    if (!d) return { patternId: id, level: "warn", message: `${title} has not been tested on ${version} yet.` };
    if (d.contentHash !== p.contentHash) return { patternId: id, level: "warn", message: `${title} changed since the ${version} check; re-run it.` };
    if (d.compile !== "pass" || d.scan !== "pass") return { patternId: id, level: "error", message: `${title} does not compile on ${version}: mods built with it need an update for ${version}.` };
    if (d.runtime === "fail") return { patternId: id, level: "error", message: `${title} compiles but fails when loaded on ${version}: mods built with it need an update.` };
    if (d.runtime !== "pass") return { patternId: id, level: "warn", message: `${title} compiles on ${version}; not load-tested yet.` };
    return { patternId: id, level: "ok", message: `${title}: works on ${version}.` };
  });
}

/** Worst level of a risk list (for one badge). */
export function worstRisk(r: LibraryRisk[]): LibraryRisk["level"] {
  return r.some((x) => x.level === "error") ? "error" : r.some((x) => x.level === "warn") ? "warn" : "ok";
}

