// Cyrus Pattern Library (service 0.6): schema/licence lint, the built file, hashing + status,
// deterministic selection, prompt stability, API stubs, attach + relocation, notices, and the
// lifecycle-facing status helpers. Pure: no AI call, no javac, no network. The real compile and
// Paper-server checks are `tools/library.js verify|runtime` on node-2 (records in verify.json).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { LIBRARY_CATEGORY_IDS, LIBRARY_LICENSES, type PatternLibrary } from "../lib/cyrus/library/types";
import { libraryHealth, minecraftLibrary, modLibraryRisk, patternStatus, worstRisk, type DriftReport } from "../lib/cyrus/library/status";

/* eslint-disable @typescript-eslint/no-require-imports, @typescript-eslint/no-explicit-any */
const L = require("../services/modbuilder/library.js") as any;
const T = require("../services/modbuilder/tools/library.js") as any;
const P = require("../services/modbuilder/prompts.js") as any;

const SVC = path.resolve(__dirname, "../services/modbuilder");
const sources = () => L.readSources("minecraft");
const built = (): PatternLibrary => JSON.parse(fs.readFileSync(path.join(SVC, "library/minecraft.json"), "utf8"));
const allVerified = (lib: PatternLibrary): PatternLibrary => ({ ...lib, patterns: lib.patterns.map((p) => ({ ...p, verifiedOn: p.versions })) });
const prompts = fs.readFileSync(path.join(SVC, "eval/prompts.jsonl"), "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));

describe("library sources", () => {
  it("lint passes (schema, licences, no literals, sizes, harness present)", () => {
    assert.deepEqual(T.lint(sources()), []);
  });
  it("has at least 25 patterns, all Nxeon-authored, using only universal categories", () => {
    const s = sources();
    assert.ok(s.length >= 25, `only ${s.length}`);
    for (const p of s) {
      assert.equal(p.source.kind, "nxeon", p.id);
      assert.ok((LIBRARY_CATEGORY_IDS as readonly string[]).includes(p.category), p.id);
    }
  });
  it("the category list matches the routing agent's universal set", () => {
    assert.deepEqual([...LIBRARY_CATEGORY_IDS], ["environment", "creatures", "weapons", "items", "magic", "vehicles", "gameplay", "quests", "minigames", "economy", "admin", "utility", "interface", "visuals", "audio", "performance"]);
  });
  it("top-level class names are unique across the library (attach mode shares one package)", () => {
    const names = sources().flatMap((p: any) => p.files.map((f: any) => f.path));
    assert.equal(new Set(names).size, names.length);
  });
  it("lint rejects disallowed licences, missing provenance and unsafe literals", () => {
    const base = sources().find((p: any) => p.id === "cooldowns");
    const bad = (patch: any, files?: any) => T.lint([{ ...base, ...patch, files: files || base.files }]).join("\n");
    assert.match(bad({ source: { kind: "third-party", license: "GPL-3.0-only", author: "x", url: "https://x", commit: "a".repeat(40), retrieved: "2026-10-08", attribution: "x", modified: true } }), /licence GPL-3.0-only not allowed/);
    assert.match(bad({ source: { kind: "third-party", license: "CC-BY-SA-4.0", author: "x", url: "https://x", commit: "a".repeat(40), retrieved: "2026-10-08", attribution: "x", modified: true } }), /not allowed/);
    assert.match(bad({ source: { kind: "third-party", license: "MIT", author: "x", url: "https://x", commit: "main", retrieved: "2026-10-08", modified: false } }), /exact 40-char commit[\s\S]*needs source.attribution/);
    assert.match(bad({ source: { kind: "opted-in-build", license: "LicenseRef-Cyrus-Contributor-Grant", retrieved: "2026-10-08" } }), /consentId/);
    assert.match(bad({}, [{ path: "Cooldowns.java", code: 'package __PKG__;\npublic class Cooldowns { String u = "https://evil.example/x"; }' }]), /URL literal/);
    assert.match(bad({}, [{ path: "Cooldowns.java", code: 'package __PKG__;\npublic class Cooldowns { String u = "0f8fad5b-d9cb-469f-a165-70867728950e"; }' }]), /hard-coded UUID/);
    assert.match(bad({ frequency: "common", retrieval: "auto" }), /CloudAPIBench/);
  });
  it("the allow-lists exclude copyleft and ShareAlike licences", () => {
    const all = Object.values(LIBRARY_LICENSES).flat() as string[];
    for (const x of ["GPL-3.0", "GPL-3.0-only", "LGPL-3.0", "AGPL-3.0", "CC-BY-SA-4.0", "MPL-2.0"]) assert.ok(!all.includes(x), x);
    for (const [k, v] of Object.entries(L.ALLOWED)) assert.deepEqual(v, (LIBRARY_LICENSES as any)[k]);
  });
});

describe("built library", () => {
  it("library/minecraft.json is up to date with the sources", () => {
    const fresh = L.build("minecraft", { gameVersions: built().gameVersions, previous: built() });
    assert.equal(JSON.stringify(fresh), JSON.stringify(built()), "run: node services/modbuilder/tools/library.js build");
  });
  it("content hashes change with the code and invalidate verification", () => {
    const p = sources()[0];
    const h1 = L.contentHash(p);
    const h2 = L.contentHash({ ...p, files: [{ ...p.files[0], code: p.files[0].code + "\n// edit" }] });
    assert.notEqual(h1, h2);
    const rec = { version: "1.21.4", contentHash: h1, compile: "pass", scan: "pass", runtime: "pass" };
    assert.equal(L.statusOf({ ...p, contentHash: h1, versions: ["1.21.4"] }, { "1.21.4": rec }).status, "verified");
    assert.equal(L.statusOf({ ...p, contentHash: h2, versions: ["1.21.4"] }, { "1.21.4": rec }).status, "unverified");
    assert.equal(L.statusOf({ ...p, contentHash: h1, versions: ["1.21.4"] }, { "1.21.4": { ...rec, runtime: "not-run" } }).status, "compiled");
    assert.equal(L.statusOf({ ...p, contentHash: h1, versions: ["1.21.4", "1.21.1"] }, { "1.21.4": rec, "1.21.1": { ...rec, version: "1.21.1", compile: "fail" } }).status, "failing");
    assert.equal(L.statusOf({ ...p, contentHash: h1, versions: ["1.21.4"] }, { "1.21.4": { ...rec, scan: "warn" } }).status, "failing");
  });
  it("only patterns verified on a version are usable on it", () => {
    const lib = built();
    for (const v of lib.gameVersions) for (const p of L.usable(lib, v)) assert.ok(p.verifiedOn.includes(v));
  });
});

describe("retrieval", () => {
  const lib = allVerified(built());
  it("adversarial and simple common-API prompts get nothing inlined", () => {
    for (const p of prompts.filter((x: any) => x.adversarial || x.cls === "simple")) assert.deepEqual(L.select(p.prompt, p.v, lib).ids, [], p.key);
  });
  it("never inlines a common-API pattern, respects the cap and adds required patterns", () => {
    for (const p of prompts) {
      const s = L.select(p.prompt, p.v, lib, { max: 3, maxTokens: 3500 });
      assert.ok(s.tokens <= 3500, p.key);
      for (const id of s.ids) {
        const pat = lib.patterns.find((x) => x.id === id)!;
        for (const r of pat.requires) assert.ok(s.ids.includes(r), `${p.key}: ${id} needs ${r}`);
      }
      for (const id of s.ids) assert.equal(lib.patterns.find((x) => x.id === id)!.frequency === "common" && !lib.patterns.some((x) => x.requires.includes(id) && s.ids.includes(x.id)), false, `${p.key}: ${id}`);
    }
  });
  it("is deterministic and finds the obvious ones", () => {
    const pick = (k: string) => { const p = prompts.find((x: any) => x.key === k); return L.select(p.prompt, p.v, lib).ids; };
    assert.deepEqual(pick("m15-afk"), pick("m15-afk"));
    assert.ok(pick("m03-warpgui").includes("chest-menu"));
    assert.ok(pick("m10-growth").includes("attribute-modifier"));
    assert.ok(pick("c04-claims").includes("chunk-claims"));
    assert.ok(pick("m09-chatmod").includes("chat-guard"));
  });
  it("the index is byte-identical per version and empty when the library is off", () => {
    assert.equal(L.indexText("1.21.4", lib, "index"), L.indexText("1.21.4", lib, "index"));
    assert.equal(L.indexText("1.21.4", lib, "off"), "");
    assert.equal(L.indexText("1.21.4", lib, "attach"), "");
    assert.ok(L.indexText("1.21.4", lib, "index").length < 3500, "index stays small (cached prefix)");
  });
  it("MB_LIBRARY unset keeps the 0.5 system prompt and knowledge string", () => {
    assert.equal(L.MODE, "off");
    assert.ok(!/PATTERN LIBRARY/.test(P.systemPrompt("1.21.4")));
    assert.ok(!/lib-/.test(P.knowledgeVersion()));
  });
});

describe("attach mode", () => {
  const lib = allVerified(built());
  it("stubs keep the public API and drop the bodies", () => {
    const code = lib.patterns.find((p) => p.id === "economy-ledger")!.files[0].code;
    const stub = L.stubOf(code);
    assert.match(stub, /public synchronized Result transfer\(UUID from, UUID to, long amount\);/);
    assert.match(stub, /OK, INSUFFICIENT_FUNDS/);
    assert.ok(!/addExact/.test(stub));
    assert.ok(stub.length < code.length * 0.5);
  });
  it("attaches, relocates what the plugin uses into its package, keeps whole patterns, drops the rest", () => {
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "lib-attach-"));
    const placed = L.attach(ws, ["paged-menu", "cooldowns", "economy-ledger"], lib);
    assert.deepEqual(placed, ["chest-menu", "paged-menu", "cooldowns", "economy-ledger"]);
    assert.ok(fs.existsSync(path.join(ws, "src/main/java/cyruslib/Menu.java")));
    // what a model would write: uses Cooldowns + Menu, not PagedMenu or Ledger
    fs.mkdirSync(path.join(ws, "src/main/resources"), { recursive: true });
    fs.writeFileSync(path.join(ws, "src/main/resources/plugin.yml"), "name: Warps\nmain: dev.nxeon.plugins.warps.Warps\n");
    fs.mkdirSync(path.join(ws, "src/main/java/dev/nxeon/plugins/warps"), { recursive: true });
    fs.writeFileSync(path.join(ws, "src/main/java/dev/nxeon/plugins/warps/Warps.java"),
      "package dev.nxeon.plugins.warps;\nimport cyruslib.Cooldowns;\nimport cyruslib.Menu;\npublic class Warps { Cooldowns c; Menu m; String s = \"mycyruslib.x\"; }\n");
    const r = L.relocate(ws, L.groupsFor(placed, lib));
    assert.equal(r.ok, true);
    assert.deepEqual(r.used, ["Cooldowns", "Menu", "MenuListener"]);
    assert.deepEqual(r.removed, ["Ledger", "PagedMenu"]);
    assert.ok(!fs.existsSync(path.join(ws, "src/main/java/cyruslib")));
    const moved = fs.readFileSync(path.join(ws, "src/main/java/dev/nxeon/plugins/warps/cyruslib/Menu.java"), "utf8");
    assert.match(moved, /^package dev\.nxeon\.plugins\.warps\.cyruslib;/m);
    const own = fs.readFileSync(path.join(ws, "src/main/java/dev/nxeon/plugins/warps/Warps.java"), "utf8");
    assert.match(own, /import dev\.nxeon\.plugins\.warps\.cyruslib\.Cooldowns;/);
    assert.match(own, /"mycyruslib\.x"/, "only real references are rewritten");
    assert.deepEqual(L.patternsForClasses(r.used, lib), ["chest-menu", "cooldowns"]);
  });
  it("waits when the main package is not known yet", () => {
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "lib-attach-"));
    L.attach(ws, ["cooldowns"], lib);
    assert.equal(L.relocate(ws).ok, false);
    assert.ok(fs.existsSync(path.join(ws, "src/main/java/cyruslib/Cooldowns.java")));
  });
  it("the attach prompt says not to read or rewrite the classes", () => {
    const b = L.attachBlock(["cooldowns"], "1.21.4", lib);
    assert.match(b, /Do NOT Read, rewrite/);
    assert.match(b, /public long tryUse\(Player player\);/);
  });
});

describe("notices", () => {
  it("no notice for Nxeon-authored patterns; MIT/Apache/BSD patterns produce one", () => {
    const lib = built();
    assert.equal(L.noticesFor(lib.patterns.map((p) => p.id), lib), "");
    const third: any = { ...lib, patterns: [{ ...lib.patterns[0], id: "x", source: { kind: "third-party", license: "MIT", url: "https://example.org/r", commit: "a".repeat(40), attribution: "Copyright (c) 2026 Someone. MIT License.", modified: true } }] };
    assert.match(L.noticesFor(["x"], third), /Copyright \(c\) 2026 Someone/);
  });
});

describe("status for lifecycle", () => {
  const lib = built();
  const p0 = lib.patterns[0];
  const fake: PatternLibrary = {
    ...lib,
    gameVersions: ["1.21.4", "1.21.11"],
    patterns: [
      { ...p0, id: "good", versions: ["1.21.4", "1.21.11"], verifiedOn: ["1.21.4", "1.21.11"] },
      { ...p0, id: "bad", versions: ["1.21.4", "1.21.11"], verifiedOn: ["1.21.4"], verification: [{ ...(p0.verification[0] || {} as any), version: "1.21.11", contentHash: p0.contentHash, compile: "fail", scan: "block", runtime: "not-run", warnings: [], date: "", tools: { javac: "", apiJar: "", harness: "" } }] },
    ],
    removed: [{ id: "gone", at: "2026-10-08", reason: "owner withdrew consent" }],
  };
  it("patternStatus per version", () => {
    assert.equal(patternStatus(fake, "good", "1.21.11"), "verified");
    assert.equal(patternStatus(fake, "bad", "1.21.11"), "failing");
    assert.equal(patternStatus(fake, "bad", "1.21.8"), "not-claimed");
    assert.equal(patternStatus(fake, "nope", "1.21.4"), "unknown-pattern");
  });
  it("modLibraryRisk uses records, then drift reports", () => {
    assert.equal(worstRisk(modLibraryRisk(fake, ["good"], "1.21.11")), "ok");
    assert.equal(worstRisk(modLibraryRisk(fake, ["good", "bad"], "1.21.11")), "error");
    assert.equal(worstRisk(modLibraryRisk(fake, ["good"], "1.22")), "warn");
    const drift: DriftReport = { version: "1.22", date: "", apiJar: "", broken: ["good"], patterns: { good: { contentHash: p0.contentHash, compile: "fail", scan: "pass", warnings: 0 } } };
    assert.equal(worstRisk(modLibraryRisk(fake, ["good"], "1.22", drift)), "error");
    assert.equal(worstRisk(modLibraryRisk(fake, ["gone"], "1.21.4")), "ok");
  });
  it("libraryHealth counts every claimed version of the real library", () => {
    const h = libraryHealth(minecraftLibrary);
    assert.equal(h.length, minecraftLibrary.gameVersions.length);
    for (const x of h) assert.equal(x.verified + x.compiled + x.failing + x.unverified, x.total);
  });
});

