    assert.ok(!r.library.attached.includes("cooldowns"), "common-API patterns are never attached");
    const call = lines("claude.log")[0];
    assert.ok(call.attachedAtStart.includes("PlayerDataStore.java"), "placed before the model ran");
    assert.equal(call.hasStubs, true);
