    assert.equal(r.library.relocated.package, "dev.nxeon.plugins.heal.cyruslib");
    assert.deepEqual(r.library.usedPatterns, ["player-data-store"]);
    const compiled = lines("javac.log").at(-1);
    assert.ok(compiled.includes("dev/nxeon/plugins/heal/cyruslib/PlayerDataStore.java"), JSON.stringify(compiled));
    assert.ok(!compiled.some((f: string) => f.startsWith("cyruslib/")), "nothing left in the shared package");
