    assert.match(src, /^import dev\.nxeon\.plugins\.heal\.cyruslib\.PlayerDataStore;$/m);
    assert.ok(r.files.every((f: { path: string }) => !f.path.startsWith(".cyrus-library") && !f.path.startsWith("src/main/java/cyruslib/")));
  });
});
